    LazyLock::new(|| hipfire_config::developer_bool("HIPFIRE_QWEN4_SHARED_GU_PM", true));
/// Waves (16 channels each) per workgroup of the entry the route launches: the
/// `_w8` entry (128 channels x 128 tokens per workgroup). The `_w4` entry is the oracle's
/// comparison arm.
pub const QWEN4_SHARED_GU_PM_WAVES: u8 = 8;
/// Shape limits of the fused shared gate/up kernel: `m` channels a multiple of 16, `k` a
/// multiple of 64 (at least 64), at least one token, and the weight and X byte extents
/// below 2^31 (32-bit buffer offsets).
pub const fn qwen4_shared_gu_pm_shape(m: usize, k: usize, n: usize) -> bool {
    m > 0
        && m % 16 == 0
        && k >= 64
        && k % 64 == 0
        && n > 0
        && (m as u128) * (k as u128) * 2 < (1u128 << 31)
        && (n as u128) * (k as u128) * 2 < (1u128 << 31)
        && (n as u128) * (m as u128) * 2 < (1u128 << 31)
}
/// Channels per workgroup (eight waves of sixteen) of `mtp_dense_det_pm_gfx1151_w8`.
pub const MTP_DENSE_DET_PM_TILE_M: usize = 128;
/// Projection rows (tokens) per workgroup of `mtp_dense_det_pm_gfx1151_w8`.
pub const MTP_DENSE_DET_PM_TILE_N: usize = 256;
/// Entry of the standalone MTP dense DET module (`kernels::MTP_DENSE_DET_PM_GFX1151`).
pub const MTP_DENSE_DET_PM_ENTRY: &str = "mtp_dense_det_pm_gfx1151_w8";
/// Module and entry of the MTP append DET Q8_0 -> F16 weight converter
/// (`kernels::MTP_Q8_DET_PM_GFX1151`, launched by `Gpu::ensure_q8_0_f16_shadow`).
pub const MTP_Q8_DET_PM_MODULE: &str = "mtp_q8_det_pm_gfx1151";
pub const MTP_Q8_DET_PM_ENTRY: &str = "mtp_q8_0_to_f16_pm_gfx1151";
/// Shape limits of the standalone MTP dense DET F16 WMMA kernel: `m` channels a multiple of 16,
/// `k` a multiple of 64 (at least 64), at least one projection row, the A16 (`m*k*2`), X16
/// (`n*k*2`) and Y32 (`n*m*4`) byte extents below 2^31 (32-bit buffer offsets) and the
/// `ceil(n / 256)` grid-y within 16 bits. One fixed tile, no split-K: no other bound.
pub const fn mtp_dense_det_pm_shape(m: usize, k: usize, n: usize) -> bool {
    m > 0
        && m % 16 == 0
        && k >= 64
        && k % 64 == 0
        && n > 0
        && (m as u128) * (k as u128) * 2 < (1u128 << 31)
        && (n as u128) * (k as u128) * 2 < (1u128 << 31)
        && (n as u128) * (m as u128) * 4 < (1u128 << 31)
        && ((n as u128) + (MTP_DENSE_DET_PM_TILE_N as u128) - 1) / (MTP_DENSE_DET_PM_TILE_N as u128)
            <= 0xffff
}
/// gfx1151 selective PM route (`HIPFIRE_QWEN4_MQ6_X4_PM`): the MQ6 X-LDS overwrite
/// launches (F32, BF16 output, and the a/b/z regions fold, all 128-row `_w8` entries of
/// `kernels::QWEN4_MQ6_X4_PM_GFX1151`, 256-token tiles) run from the certified builder
/// module at `M >= QWEN4_MQ6_X4_PM_MIN_M_GFX1151` rows (regions: summed rows) and
/// `N >= QWEN4_MQ6_X4_PM_MIN_N_GFX1151` tokens, the large FN pp8192 trunk shapes. Smaller
/// launches, the `_w4` entries and the HC-write (`hcw`) entry stay on hipcc / U3.
pub const QWEN4_MQ6_X4_PM_MIN_M_GFX1151: usize = 2560;
/// See [`QWEN4_MQ6_X4_PM_MIN_M_GFX1151`].
pub const QWEN4_MQ6_X4_PM_MIN_N_GFX1151: usize = 2048;
/// `HIPFIRE_QWEN4_MQ4_X4_PM` (on unless `0`): exact gfx1151 MQ4G256V2 prefill
/// (`Gpu::gemm_mq4g256v2_xf16` and its regions / HC-write siblings) runs from the
/// certified builder module `kernels::QWEN4_MQ4_X4_PM_GFX1151`; `0` keeps hipcc
/// `gemm_mq4g256v2_residual_wmma_gfx11_bt4` for the plain F32 launch (same bytes) and
/// leaves BF16 output, regions and the HC-write fusion off. Read once.
static QWEN4_MQ4_X4_PM: LazyLock<bool> =
    LazyLock::new(|| hipfire_config::developer_bool("HIPFIRE_QWEN4_MQ4_X4_PM", true));
/// Smallest token count of the gfx1151 MQ4G256V2 shared-F16 prefill route: the floor of
/// the hipcc BT4 route it replaces (below it the generic projection keeps its routes);
/// one 256-token PM tile handles any partial N above it.
pub const QWEN4_MQ4_X4_MIN_N_GFX1151: usize = 96;

/// Header-planner counterpart of the launcher's selective native MQ6 arm.
/// The process-frozen switch is supplied explicitly so shape policy is pure.
pub(crate) fn mq6_x4_pm_gfx1151_selected(arch: &str, enabled: bool, m: usize, n: usize) -> bool {
    enabled && arch == "gfx1151" && mq6_x4_pm_gfx1151_shape(m, n)
}

/// Shared HC-down tile admissions. Capture/recording retain their incumbent
/// gfx1151 tile; gfx1201's split-K choice is independent of those modes.
pub(crate) fn hc_down_tile_selected(
    arch: &str,
    enabled: bool,
    m: usize,
    k: usize,
    rows: usize,
    recording: bool,
    capturing: bool,
) -> bool {
    enabled
        && match arch {
            "gfx1201" => m == 320 && k % 256 == 0,
            "gfx1151" => m == 320 && k == 10240 && rows >= 2048 && !recording && !capturing,
            _ => false,
        }
}

/// gfx1100 HC `input_mix_down` fill tile (`HIPFIRE_QWEN4_HC_MIX_FILL80_GFX1100`, default on):
/// exact gfx1100, M == 320 (four full 80-row tiles: no ragged M tile) and K % 64 == 0.
/// Bit-identical to the 64 x 64 / k64 pipelined tile it replaces (same ascending-K WMMA chain
/// per output element); any other shape keeps the generic M < 512 tile.
pub(crate) fn hc_mix_fill80_gfx1100_selected(
    arch: &str,
    enabled: bool,
    m: usize,
    k: usize,
) -> bool {
    enabled && arch == "gfx1100" && m == 320 && k % 64 == 0
}

/// Smallest route-row count the gfx1201 fused HC-down + activation kernel takes; below it the
/// three-launch chain wins.
pub const HC_DOWN_FUSED_MIN_ROWS: usize = 1536;

/// Smallest route-row count the gfx1151 fused HC-down + activation kernel takes. Measured on
/// Halo (fused vs the chain's GEMM + activation, us per call, 3 runs agree to 1 %): 512 rows
/// 209 vs 178, 1024 rows 272 vs 309, 1536 rows 508 vs 557, 2048 rows 527 vs 862; the chain
/// (64 x 64 tile below 2048 rows, 160 x 64 from there) stays below 1024.
pub const HC_DOWN_FUSED_GFX1151_MIN_ROWS: usize = 1024;

/// gfx1201 / gfx1151 HC-down (320 x 10240) + activation fused into one launch
/// (`HIPFIRE_QWEN4_HC_DOWN_FUSED`, default on, `0` keeps the chain).
pub(crate) fn hc_down_fused_selected(
    arch: &str,
    enabled: bool,
    m: usize,
    k: usize,
    rows: usize,
    recording: bool,
    capturing: bool,
) -> bool {
    let min_rows = match arch {
        "gfx1201" => HC_DOWN_FUSED_MIN_ROWS,
        "gfx1151" => HC_DOWN_FUSED_GFX1151_MIN_ROWS,
        _ => return false,
    };
    enabled
        && m == 320
        && k == 10240
        && rows >= min_rows
        && rows.checked_mul(k * 2).is_some_and(|b| b < (1usize << 32))
        && !recording
        && !capturing
}

/// gfx1201's symmetric MoE uses the native image even when the gfx1151
/// native-image kill switch is off.
pub(crate) fn qwen4_moe_sym_native_selected(arch: &str, enabled: bool) -> bool {
    arch == "gfx1201" || (arch == "gfx1151" && enabled)
}
/// HC-down (320 x 10240) tile, default on, `0` keeps the incumbent tile. gfx1151 (rows >= 2048):
/// 160 x 64 pipelined instead of 64 x 64. gfx1201: [`LdsTileSplitK::HC_DOWN_GFX1201`] instead
/// of the 64 x 128 / k64 split-K tile.
static QWEN4_HC_DOWN_TILE: std::sync::LazyLock<bool> =
    std::sync::LazyLock::new(|| hipfire_config::developer_bool("HIPFIRE_QWEN4_HC_DOWN_TILE", true));
/// Fused HC-down + activation (gfx1201, gfx1151), default on, `0` restores the chain.
static QWEN4_HC_DOWN_FUSED: std::sync::LazyLock<bool> = std::sync::LazyLock::new(|| {
    hipfire_config::developer_bool("HIPFIRE_QWEN4_HC_DOWN_FUSED", true)
});
/// Tokens from which the F16 WMMA arms are used (measured on gfx1151; the MoE gate/up
/// arm is slower below ~450; the others break even or win).
pub const QWEN4_F16_WMMA_MIN_TOKENS: usize = 512;

/// The capability half of the Qwen4 F16 WMMA route, the ONE predicate behind
/// both the runtime ([`Gpu::qwen4_f16_wmma_applies`]) and the placement census
/// of the model-lifetime BF16 -> F16 weight shadows
/// (`Gpu::ensure_bf16_f16_shadow`): gfx11 wave32 WMMA, or the gfx1201 opt-in
/// (`gfx1201_optin`, the knob behind [`Gpu::qwen4_f16_wmma_gfx1201`]).
/// Capability, never an arch name: every part with `has_wmma_w32` runs the
/// route.
pub fn qwen4_f16_shadow_capable(caps: &crate::arch_caps::ArchCaps, gfx1201_optin: bool) -> bool {
    caps.has_wmma_w32() || (caps.is_gfx1201() && gfx1201_optin)
}

/// The whole route predicate of [`Gpu::qwen4_f16_wmma_applies`] over explicit
/// facts, so a CPU proof can compare the runtime against the placement census
/// without a device: capability ([`qwen4_f16_shadow_capable`]), a BF16
/// weight, `route_rows >= QWEN4_F16_WMMA_MIN_TOKENS`, `K % 64 == 0`, no
/// recorder or capture active (`route_open`) and not opted out
/// (`f16_wmma_enabled`).
pub fn qwen4_f16_wmma_applies_for(
    caps: &crate::arch_caps::ArchCaps,
    gfx1201_optin: bool,
    weight_is_bf16: bool,
    route_rows: usize,
    k: usize,
    route_open: bool,
    f16_wmma_enabled: bool,
) -> bool {
    qwen4_f16_shadow_capable(caps, gfx1201_optin)
        && weight_is_bf16
        && route_rows >= QWEN4_F16_WMMA_MIN_TOKENS
        && k % 64 == 0
        && route_open
        && f16_wmma_enabled
}

/// One instantiation of the parameterised LDS-staged WMMA GEMM
/// (`kernels/src/gemm_f16_x_f16_wmma_lds256.hip`).
///
/// The four axes are independent and control different things:
///
/// * `bm × bn` — block macro-tile. DRAM intensity `bm·bn/(bm+bn)` FLOP/byte,
///   and, more importantly on the measured archs, `bn` sets how many times A is
///   streamed: with `grid.x` along M the resident blocks share an X slab, so
///   real traffic is roughly `|A|·(B/bn) + |X|`.
/// * `wm × wn` — wave register tile. LDS intensity `wm·wn/(2(wm+wn))`
///   FLOP/byte, and `wm·wn/32` accumulator VGPRs per lane.
/// * `ks` — K elements staged per barrier pair. Sets the LDS footprint
///   `(bm+bn)·ks·2` bytes; a `bn` past 256 only fits at `ks = 32`.
/// * `swap` — put B on `grid.x` instead of M, reversing which operand the
///   concurrently-resident blocks share.
///
/// Only the combinations in [`Gpu::LDS_TILE_VARIANTS`] have a compiled entry
/// point; [`LdsTile::entry`] names it.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct LdsTile {
    pub bm: usize,
    pub bn: usize,
    pub wm: usize,
    pub wn: usize,
    pub ks: usize,
    pub swap: bool,
    /// Software-pipelined main loop: stage `k0 + ks`'s global loads are issued
    /// before stage `k0`'s WMMA, so their DRAM latency runs under the math
    /// instead of stalling the wave at the top of every stage. Same barriers,
    /// same K summation order, bit-exact against `pipe = false` — see the
    /// SOFTWARE PIPELINING note in the kernel source. Only the tiles in
    /// [`Gpu::LDS_EPI_TILES`] have a pipelined entry point (`_p`), and
    /// 128×128 / 64×64 k64 deliberately does not: it spills.
    pub pipe: bool,
}

impl LdsTile {
    pub const fn new(bm: usize, bn: usize, wm: usize, wn: usize, ks: usize, swap: bool) -> Self {
        Self {
            bm,
            bn,
            wm,
            wn,
            ks,
            swap,
            pipe: false,
        }
    }

    /// The same tile with the software-pipelined main loop.
    pub const fn pipelined(self) -> Self {
        Self { pipe: true, ..self }
    }

    /// gfx1100 HC input_mix_down (M = 320; [`hc_mix_fill80_gfx1100_selected`]): an 80 x 32
    /// workgroup of two 80 x 16 waves, grid 4 x ceil(N / 32) (192 waves at N = 768 instead of
    /// the 64 x 64 tile's 120), pinned fragment schedule. Not in [`Gpu::LDS_TILE_VARIANTS`]:
    /// it has no plain twin and no fused-epilogue entries, and no tile chain can reach it.
    pub const HC_MIX_FILL80_GFX1100: Self = Self::new(80, 32, 80, 16, 64, false).pipelined();

    /// The same tile with the plain load → barrier → WMMA → barrier main loop.
    /// This is what `HIPFIRE_FLUX_GEMM_PIPE=0` selects.
    pub const fn unpipelined(self) -> Self {
        Self {
            pipe: false,
            ..self
        }
    }

    /// Kernel entry-point name, matching the `WLDS_KERNEL` naming in the .hip.
    pub fn entry(&self) -> String {
        format!(
            "gemm_wmma_lds_{}_{}_{}_{}_k{}{}{}",
            self.bm,
            self.bn,
            self.wm,
            self.wn,
            self.ks,
            if self.swap { "_sw" } else { "" },
            if self.pipe { "_p" } else { "" }
        )
    }

    /// Short table label: `bm×bn/wm×wn k<ks>[sw][p]`.
    pub fn label(&self) -> String {
        format!(
            "{}x{}/{}x{}k{}{}{}",
            self.bm,
            self.bn,
            self.wm,
            self.wn,
            self.ks,
            if self.swap { "sw" } else { "" },
            if self.pipe { "p" } else { "" }
        )
    }

    /// Entry-point name of the fused-epilogue instantiation with `suffix`
    /// (`_o16`, `_o16g`, `_gr`, `_gra`, `_a`) — the `EPI = 0` name plus the
    /// suffix, matching `WLDS_EPI_SET` in the .hip.
    pub fn entry_epi(&self, suffix: &str) -> String {
        format!("{}{}", self.entry(), suffix)
    }
}

/// One tile of the split-K LDS WMMA GEMM
/// (`kernels/src/gemm_f16_x_f16_wmma_lds_splitk.hip`, gfx1201 and gfx1151):
/// block `bm × bn`, wave `wm × wn`, K staged `ks` (64 unless [`LdsTileSplitK::k_stage`]) at
/// a time, optional software pipelining and a deterministic `split`-way K split.
/// [`LdsTileSplitK::entry`] names it.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct LdsTileSplitK {
    pub bm: usize,
    pub bn: usize,
    pub wm: usize,
    pub wn: usize,
    pub pipe: bool,
    pub split: usize,
    pub ks: usize,
}

impl LdsTileSplitK {
    pub const fn new(bm: usize, bn: usize, wm: usize, wn: usize, pipe: bool, split: usize) -> Self {
        Self {
            bm,
            bn,
            wm,
            wn,
            pipe,
            split,
            ks: 64,
        }
    }

    /// The same tile with K staged `ks` (32 or 64) elements per barrier pair.
    pub const fn k_stage(self, ks: usize) -> Self {
        Self { ks, ..self }
    }

    /// gfx1201 HC input_mix_down (M = 320, K % 256 == 0, `HIPFIRE_QWEN4_HC_DOWN_TILE`):
    /// 160 x 80 of five 32 x 80 waves, K staged 32, the 64 x 128 p_s4 tile's four K
    /// splits, so the partials (and the reduced output) are bytewise that tile's.
    /// 15360 B of LDS per workgroup instead of 24576. R9700, 320 x 10240, lab harness
    /// (`qcal/release-0.4.1/hc-down-g0`): 447 -> 384 us at B = 4096, 887 -> 714 us at 8192.
    pub const HC_DOWN_GFX1201: Self = Self::new(160, 80, 32, 80, true, 4).k_stage(32);

    /// Bytes of the shared K-split partials scratch (`split * rows * m` F32)
    /// this tile writes for `rows` token rows of `m` outputs, `None` on overflow.
    pub fn partials_bytes(&self, rows: usize, m: usize) -> Option<usize> {
        self.split
            .checked_mul(rows)?
            .checked_mul(m)?
            .checked_mul(std::mem::size_of::<f32>())
    }

    /// Kernel entry-point name, matching `SK_KERNEL` in the .hip.
    pub fn entry(&self) -> String {
        format!(
            "qwen4_wmma_lds_{}_{}_{}_{}_k{}{}{}",
            self.bm,
            self.bn,
            self.wm,
            self.wn,
            self.ks,
            if self.pipe { "_p" } else { "" },
            if self.split > 1 {
                format!("_s{}", self.split)
            } else {
                String::new()
            }
        )
    }
}

/// Static entry names for the four admitted pitched, unsplit gfx1201 tiles.
fn splitk_ld_entry(tile: LdsTileSplitK) -> Option<&'static str> {
    match (
        tile.bm, tile.bn, tile.wm, tile.wn, tile.pipe, tile.split, tile.ks,
    ) {
        (64, 64, 32, 64, true, 1, 64) => Some("qwen4_wmma_lds_64_64_32_64_k64_p_ld"),
        (64, 128, 32, 64, true, 1, 64) => Some("qwen4_wmma_lds_64_128_32_64_k64_p_ld"),
        (128, 128, 32, 64, false, 1, 64) => Some("qwen4_wmma_lds_128_128_32_64_k64_ld"),
        (128, 256, 32, 64, false, 1, 64) => Some("qwen4_wmma_lds_128_256_32_64_k64_ld"),
        _ => None,
    }
}

/// Geometry admitted by the gfx1201-only pitched, unsplit LDS route.
fn splitk_ld_supported(tile: LdsTileSplitK, k: usize, lda: usize, ldx: usize) -> bool {
    k > 0
        && k % 64 == 0
        && lda >= k
        && ldx >= k
        && lda % 16 == 0
        && ldx % 16 == 0
        && splitk_ld_entry(tile).is_some()
}

/// Fused epilogue for [`Gpu::gemm_f16_x_f16_wmma_lds_epi`].
///
/// Every FLUX MMDiT GEMM is followed by a fixed elementwise pass — a cast to
/// F16 for the next GEMM's activation, a GELU, a gated residual accumulation,
/// or the sum of the two halves of a split `linear2`. Each of those is a
/// separate kernel that re-reads and re-writes the whole `B × M` matrix (226 MB
/// each way at B = 4608, M = 12288, on a part with 90 GB/s of DRAM). Selecting
/// them here folds them into the GEMM's store instead.
///
/// The evaluation order is fixed by the kernel and reproduced by the parity
/// gate:
///
/// ```text
/// v  = acc                        (the WMMA F32 accumulator)
/// v += addin[b, m]                if `addin`
/// v += bias[m]                    if `bias` (same expression as EPI = 0)
/// v  = gelu_tanh(v)               if `gelu`
/// v  = fma(gate[m], v, residual[b, m])   if `gate`/`residual`
/// y[b, m] = v                     (RNE to F16 if `out_f16`)
/// ```
///
/// `residual` (and `addin`) MAY alias `y`: element `(b, m)` is read and written
/// by the same thread at the same flat index, so the in-place gated update
/// Task 5 needs is race-free. See the ALIASING note in the kernel source.
/// anything else is a launcher error naming the entry that would be needed.
#[derive(Default, Clone, Copy)]
pub struct GemmEpilogue<'a> {
    /// Store `_Float16` (round-to-nearest-even) instead of F32. `y.dtype` must
    /// match.
    pub out_f16: bool,
    /// Apply GELU-tanh to `acc + bias`, bit-identically to `gelu_tanh_f32`.
    pub gelu: bool,
    /// F32 `[B, M]` matrix added into the accumulator before the bias.
    pub addin: Option<&'a GpuTensor>,
    /// F32 `[M]` per-output-row gate. Requires `residual`.
    pub gate: Option<&'a GpuTensor>,
    /// F32 `[B, M]` residual the gated product is added to. Requires `gate`.
    /// May alias `y`.
    pub residual: Option<&'a GpuTensor>,
    /// Round value, row gate, residual, product and sum to BF16 independently.
    /// `gate` is `[B]`, rather than `[M]`; output remains BF16-rounded F32.
    pub bf16_scaled_add: bool,
}

/// `GpuTensor` has no `Debug`, so print what actually identifies an epilogue:
/// its mask and the suffix that mask maps to.
impl std::fmt::Debug for GemmEpilogue<'_> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        let mask = self.mask();
        write!(
            f,
            "GemmEpilogue({mask:#06b} {})",
            Self::entry_suffix(mask).unwrap_or("<not instantiated>")
        )
    }
}

impl<'a> GemmEpilogue<'a> {
    /// Bit 0 — store F16 instead of F32.
    pub const OUT_F16: u32 = 1;
    /// Bit 1 — GELU-tanh on `acc + bias`.
    pub const GELU: u32 = 2;
    /// Bit 2 — `acc += addin[b, m]`.
    pub const ADDIN: u32 = 4;
    /// Bit 3 — `y = residual + gate[m] · value`.
    pub const GATED: u32 = 8;
    pub const BF16_SCALED_ADD: u32 = 16;

    /// The compiled combinations, mask → entry-name suffix. These are the ones
    /// the FLUX single/double blocks use; the full 16-mask cross product is
    /// deliberately not instantiated (each entry is a kernel in a single
    /// translation unit that the JIT compiles as a whole).
    pub const SUPPORTED: &'static [(u32, &'static str)] = &[
        (Self::OUT_F16, "_o16"),
        (Self::OUT_F16 | Self::GELU, "_o16g"),
        (Self::GATED, "_gr"),
        (Self::GATED | Self::ADDIN, "_gra"),
        (Self::ADDIN, "_a"),
        (Self::BF16_SCALED_ADD, "_bsr"),
    ];

    /// The `EPI` bitmask this configuration selects. `0` is the plain
    /// F32 + bias store, i.e. exactly [`Gpu::gemm_f16_x_f16_wmma_lds_tiled`].
    pub fn mask(&self) -> u32 {
        let mut mask = 0;
        if self.out_f16 {
            mask |= Self::OUT_F16;
        }
        if self.gelu {
            mask |= Self::GELU;
        }
        if self.addin.is_some() {
            mask |= Self::ADDIN;
        }
        // Validated as both-or-neither by the launcher before this is read.
        if self.bf16_scaled_add {
            mask |= Self::BF16_SCALED_ADD;
        } else if self.gate.is_some() || self.residual.is_some() {
            mask |= Self::GATED;
        }
        mask
    }

    /// Entry-name suffix for `mask`, or `None` when nothing is instantiated.
    pub fn entry_suffix(mask: u32) -> Option<&'static str> {
        Self::SUPPORTED
            .iter()
            .find(|&&(m, _)| m == mask)
            .map(|&(_, suffix)| suffix)
    }

    /// The suffix an arbitrary mask *would* carry, for error messages. Built in
    /// the same order `WLDS_EPI_SET` names its entries — output dtype, then
    /// GELU, then gated, then add-in — so a supported mask reproduces its real
    /// suffix (`GATED | ADDIN` → `_gra`, not `_a_gr`) and an unsupported one
    /// names a plausible entry rather than a permutation of one.
    fn describe(mask: u32) -> String {
        let mut out = String::new();
        for (bit, tag) in [
            (Self::OUT_F16, "_o16"),
            (Self::GELU, "g"),
            (Self::GATED, "_gr"),
            (Self::ADDIN, "a"),
            (Self::BF16_SCALED_ADD, "_bsr"),
        ] {
            if mask & bit != 0 {
                // The first fragment carries the leading underscore; a bare
                // GELU or ADDIN still needs one.
                if out.is_empty() && !tag.starts_with('_') {
                    out.push('_');
                }
                out.push_str(tag);
            }
        }
        out
    }
}

/// Batch ceilings for the LDS-staged HFQ4-G256 GEMMs (`HIPFIRE_HFQ4G256_LDSSTAGE=1`).
/// The staged kernels win while the grid is small and lose once the added LDS
/// traffic plus the `__launch_bounds__(256,4)` occupancy cap outweigh the
/// coalesced loads. Every value below is MEASURED in-engine (`hipfire bench
/// --matrix`, matched A/B/B/A, runs 5, warmups 10, dense 27B MQ4), 2026-07-29/30:
///
///   gfx1201 (R9700, 64 CU, pinned 3.6-27B `86a5f80f…`):
///     B16 1.0902  B32 1.0489  B64 1.0300  B72 1.0914  B80 1.1079
///     B96 1.0409  B112 0.9977  B128 0.9096  B512 0.9465  B1024 0.9492
///   gfx1100 (7900 XTX, 96 CU, 3.5-27B):
///     B16 1.1044  B32 1.1324  B64 1.1719  B96 1.1786   (>=128 unreachable, see below)
///   gfx1151 (Strix Halo, 40 CU, 3.5-27B):
///     B16 1.1132  B24 1.0487  B32 1.0383  B48 1.0023  B64 0.9915
///
/// Turn points are NOT a function of CU count (gfx1201 turns at 96-112 with 64 CU,
/// gfx1151 at 32-48 with 40 CU) — an earlier CU-count reading was an artifact of a
/// coarse sweep grid. They are also NOT portable from a small model: a 0.8b canary
/// measured +11..+23% at batch 512-8192 where 27B measures -3.5..-5.4%
/// (.research/round5-verify-cost.md §17). Measure per arch on a real model.
///
/// On gfx11 the staged path is only REACHABLE below the MMQ cutoff: `gemm.rs`
/// routes `arch_caps.should_use_mmq(batch_size)` (128 on RDNA3/3.5) to the MMQ
/// kernel before the gfx11 WMMA branch, so batch >= 128 never reaches these
/// kernels there. gfx12 has no such diversion, which is why only gfx12 shows the
/// large-batch regression.
pub(crate) const LDSSTAGE_MAX_BATCH: usize = 96;

/// gfx11 (RDNA3 / RDNA3.5), both dGPU and iGPU. Re-measured on the PINNED 3.6
/// trunk `86a5f80f…` (the fixture rule: measure 3.6 when it exists), which
/// reproduced the earlier 3.5 numbers within +/-0.7 percentage points at every
/// shared batch on both parts:
///
///   gfx1100 (7900 XTX, 96 CU): B16 1.0992  B24 1.1150  B32 1.1355
///                              B48 1.1792  B64 1.1670  B96 1.1754   (all WIN)
///   gfx1151 (Strix Halo, 40 CU): B16 1.1155  B24 1.0449  B32 1.0452
///                              B48 1.0054  B64 0.9947  B96 1.0399
///
/// The iGPU has a wash band at 48-64 (worst case -0.5%, inside the 0.87-1.25%
/// run-to-run spread) and then wins again at 96 — reproducible on BOTH model
/// files. That is the non-staged kernel dipping at 96 (its OFF arm drops
/// 196.7 -> 190.3 tok/s while the staged arm stays flat at ~198), not the staged
/// kernel improving. One ceiling of 96 therefore serves both parts: it captures
/// every measured win and rides a sub-spread wash on the iGPU's 48-64 band. An
/// earlier dGPU/iGPU split (96 / 32) was collapsed once the iGPU's 96 win
/// reproduced on the correct fixture — the split bought nothing.
///
/// Batches >= 128 never reach these kernels on gfx11: `should_use_mmq` (cutoff
/// 128) diverts to MMQ before the gfx11 WMMA branch, so the whole reachable
/// domain is covered.
const LDSSTAGE_MAX_BATCH_GFX11: usize = 96;

/// `HIPFIRE_G12_IU4_V3=1` enables the K1 lean-issue IU4 module on gfx1201
/// symmetric routes (default on). Parsed once per process.
static G12_IU4_V3: LazyLock<bool> =
    LazyLock::new(|| hipfire_config::developer_bool("HIPFIRE_G12_IU4_V3", true));

#[inline]
fn g12_iu4_v3_enabled() -> bool {
    *G12_IU4_V3
}

/// Select the original certified bundle in the same binary for parity/timing controls.
static G12_IU4_B1_CONTROL: LazyLock<bool> =
    LazyLock::new(|| hipfire_config::developer_bool("HIPFIRE_G12_IU4_B1_CONTROL", false));

/// Developer A/B of iu4 builder bundles with one binary (for example the
/// previous certified bundle as a same-binary opt-out):
/// `HIPFIRE_G12_IU4_B1_BUNDLE=<path>` / `HIPFIRE_G12_IU4_B1S_BUNDLE=<path>`
/// load the token / slab bundle from a file instead of the embedded image.
/// Read once; an unreadable file fails every launch that needs the bundle.
type BundleOverride = Option<Result<Vec<u8>, String>>;
fn g12_iu4_bundle_override(var: &str) -> BundleOverride {
    let path = hipfire_config::developer_var(var).ok()?;
    Some(std::fs::read(&path).map_err(|e| format!("{var}: bundle {path}: {e}")))
}
static G12_IU4_B1_BUNDLE: LazyLock<BundleOverride> =
    LazyLock::new(|| g12_iu4_bundle_override("HIPFIRE_G12_IU4_B1_BUNDLE"));
static G12_IU4_B1S_BUNDLE: LazyLock<BundleOverride> =
    LazyLock::new(|| g12_iu4_bundle_override("HIPFIRE_G12_IU4_B1S_BUNDLE"));

fn g12_iu4_bundle(
    file: &'static BundleOverride,
    embedded: &'static [u8],
) -> HipResult<&'static [u8]> {
    match file {
        Some(Ok(image)) => Ok(image),
        Some(Err(e)) => Err(hip_bridge::HipError::new(0, e)),
        None => Ok(embedded),
    }
}

#[inline]
fn g12_iu4_b1_image() -> HipResult<&'static [u8]> {
    if *G12_IU4_B1_CONTROL {
        Ok(kernels::GEMM_MQ4G256V2_RESIDUAL_MMQ_IU4_GFX12_B1_CONTROL)
    } else {
        g12_iu4_bundle(
            &G12_IU4_B1_BUNDLE,
            kernels::GEMM_MQ4G256V2_RESIDUAL_MMQ_IU4_GFX12_B1,
        )
    }
}

#[inline]
fn g12_iu4_b1s_image() -> HipResult<&'static [u8]> {
    g12_iu4_bundle(
        &G12_IU4_B1S_BUNDLE,
        kernels::GEMM_MQ4G256V2_RESIDUAL_MMQ_IU4_GFX12_B1S,
    )
}
/// B-1 slab activation layout (`HIPFIRE_A4_SLAB`, default on; `=0` opts
/// out): the default gfx1201 A4 producers store each K128 block's
/// `block_i4_128` bytes as `[d 4N][s 4N][qs 0..31: 32N][qs 32..63: 32N]`
/// and the `_b1s` bundle stages them as whole lines. Bit-identical outputs
/// (same bytes, moved); the K-loop runs the same cycles at a higher clock
/// under the 300 W cap. Parsed once so a producer and its consumers agree.
static A4_SLAB: LazyLock<bool> =
    LazyLock::new(|| hipfire_config::developer_bool("HIPFIRE_A4_SLAB", true));
/// gfx1201 GDN input projection merge on the non-fused IU4 verify path
/// (`HIPFIRE_GDN_ZBA_FOLD`, default on; `=0` restores the four separate QKV,
/// Z, beta and alpha SETs): one QKV + Z fold launch, or the Z fold SET +
/// split. Byte-identical outputs.
static GDN_ZBA_FOLD: LazyLock<bool> =
    LazyLock::new(|| hipfire_config::developer_bool("HIPFIRE_GDN_ZBA_FOLD", true));
/// gfx1201 small-N verify schedules (`HIPFIRE_VERIFY_V64`, default on; `=0` kills): slab
/// launches of at most [`VERIFY_V64_MAX_N`] rows load the `_v64` exports of the `_b1s`
/// bundle (full_add/full_set/qkvzaset/gate_up_silu) instead of the shipped ones.
/// Byte-identical outputs.
static VERIFY_V64: LazyLock<bool> =
    LazyLock::new(|| hipfire_config::developer_bool("HIPFIRE_VERIFY_V64", true));
/// Largest launch row count (`n`) that takes the `_v64` slab exports.
const VERIFY_V64_MAX_N: usize = 128;
/// Token-fastest grid for the slab HIN producer (`HIPFIRE_A4_HIN_TOKFAST`,
/// default on; `=0` opts out): `fused_silu_mul_mq_rotate_awq_i4_hin_gfx12_slab_tokfast`
/// on grid [N, K/256] instead of the group-fastest `_slab` twin on [K/256, N].
/// The group-fastest order fills each 128-B slab-plane line from tokens 68
/// workgroups apart; token-fastest fills it from neighbouring workgroups.
/// Same per-workgroup math and stores, so byte-identical output.
static A4_HIN_TOKFAST: LazyLock<bool> =
    LazyLock::new(|| hipfire_config::developer_bool("HIPFIRE_A4_HIN_TOKFAST", true));
#[inline]
pub(crate) fn a4_hin_tokfast_enabled() -> bool {
    *A4_HIN_TOKFAST
}
/// Reciprocal-plane divide in the A4 RMSNorm slab producer
