    /// Batched GEMM for F32: Y[N,M] = B[N,K] @ A[M,K]^T.
    /// `gemm_f32.hip` uses N only to guard blockIdx.y: every row retains
    /// the singleton lane-strided K loop and shuffle tree at all verify widths.
    pub fn gemm_f32_batched(
        &mut self,
        a: &GpuTensor,
        b: &GpuTensor,
        y: &GpuTensor,
        m: usize,
        k: usize,
        n: usize,
    ) -> HipResult<()> {
        if m == 0 || n == 0 {
            return Ok(());
        }
        let bytes = f32_batched_extents(m, k, n).ok_or_else(|| {
            hip_bridge::HipError::new(1, "F32 GEMM dimensions or byte extents overflow")
        })?;
        // Either input may be a loaded weight (A for the PARO/DeltaNet alpha/beta
        // projections, B for the DFlash fc). Loaded weights are untyped `Raw`
        // byte buffers whose logical F32 dtype the caller has already matched.
        let f32_view = |t: &GpuTensor| matches!(t.dtype, DType::F32 | DType::Raw);
        if !f32_view(a)
            || !f32_view(b)
            || y.dtype != DType::F32
            || a.buf.size() < bytes[0]
            || b.buf.size() < bytes[1]
            || y.buf.size() < bytes[2]
        {
            return Err(hip_bridge::HipError::new(
                1,
                "F32 GEMM needs full-window F32 weight/activation/output views",
            ));
        }
        self.bind_thread()?;
        self.ensure_kernel(
            "gemm_f32_batched",
            kernels::GEMM_F32_SRC,
            "gemm_f32_batched",
        )?;
        // Chunk only the grid-y extent, never the K loop or reduction.
        for (off, take) in f32_batched_chunks(n) {
            let mut ap = a.buf.as_ptr();
            let mut bp = b
                .buf
                .as_ptr()
                .wrapping_byte_add(off * k * std::mem::size_of::<f32>());
            let mut yp = y
                .buf
                .as_ptr()
                .wrapping_byte_add(off * m * std::mem::size_of::<f32>());
            let mut mi = m as i32;
            let mut ki = k as i32;
            let mut ni = take as i32;
            let mut params = [
                &mut ap as *mut _ as *mut c_void,
                &mut bp as *mut _ as *mut c_void,
                &mut yp as *mut _ as *mut c_void,
                &mut mi as *mut _ as *mut c_void,
                &mut ki as *mut _ as *mut c_void,
                &mut ni as *mut _ as *mut c_void,
            ];
            launch_params_blob!(
                self,
                "gemm_f32_batched",
                [m as u32, take as u32, 1],
                [32, 1, 1],
                0,
                params; ap, bp, yp, mi, ki, ni
            )?;
        }
        Ok(())
    }
    /// Operand contract shared by the BF16-weight x F32-activation GEMMs: a
    /// full-window `[m, k]` BF16 weight, `[n, k]` F32 activation and `[n, m]`
    /// F32 output. A loaded weight is an untyped `Raw` byte buffer whose logical
    /// BF16 dtype the caller has already matched.
    fn bf16_xf32_check(
        w: &GpuTensor,
        x: &GpuTensor,
        y: &GpuTensor,
        m: usize,
        k: usize,
        n: usize,
    ) -> HipResult<()> {
        let bytes = f32_batched_extents(m, k, n).ok_or_else(|| {
            hip_bridge::HipError::new(1, "BF16-weight GEMM dimensions or byte extents overflow")
        })?;
        let ok = matches!(w.dtype, DType::BF16 | DType::Raw)
            && matches!(x.dtype, DType::F32 | DType::Raw)
            && y.dtype == DType::F32
            && w.buf.size() >= bytes[0] / 2
            && x.buf.size() >= bytes[1]
            && y.buf.size() >= bytes[2];
        if ok {
            Ok(())
        } else {
            Err(hip_bridge::HipError::new(
                1,
                "BF16-weight GEMM needs full-window BF16 weight, F32 activation and F32 output views",
            ))
        }
    }

    /// Native-BF16 weight x F32 input batched GEMM: `Y[N,M] = X[N,K] @ W[M,K]^T`.
    ///
    /// `weight` is row-major `[M, K]` BF16, `x` is row-major `[N, K]` F32,
    /// and `y` is row-major `[N, M]` F32. The device kernel widens BF16 values
    /// exactly (high-half shift) and keeps the per-output arithmetic of
    /// [`Self::gemm_f32_batched`] (lane-strided FMA sum over k, width-32
    /// shuffle tree), so it is bit-identical to that kernel run on the widened
    /// weight at every `n`. Used by Qwen4's shared expert and by Raon's mHC
    /// selector and MoE router (decode and verify row counts).
    #[allow(clippy::too_many_arguments)]
    pub fn gemm_bf16_xf32_batched(
        &mut self,
        weight: &GpuTensor,
        x: &GpuTensor,
        y: &GpuTensor,
        m: usize,
        k: usize,
        batch_size: usize,
    ) -> HipResult<()> {
        if m == 0 || batch_size == 0 {
            return Ok(());
        }
        Self::bf16_xf32_check(weight, x, y, m, k, batch_size)?;
        self.bind_thread()?;
        const KERNEL: &str = "gemm_bf16_xf32_batched";
        self.ensure_kernel(KERNEL, kernels::GEMM_BF16_XF32_BATCHED_SRC, KERNEL)?;
        // Chunk only the grid-y extent, never the K loop or reduction.
        for (off, take) in f32_batched_chunks(batch_size) {
            let mut wp = weight.buf.as_ptr();
            let mut xp = x
                .buf
                .as_ptr()
                .wrapping_byte_add(off * k * std::mem::size_of::<f32>());
            let mut yp = y
                .buf
                .as_ptr()
                .wrapping_byte_add(off * m * std::mem::size_of::<f32>());
            let mut mi = m as i32;
            let mut ki = k as i32;
            let mut ni = take as i32;
            let mut params = [
                &mut wp as *mut _ as *mut c_void,
                &mut xp as *mut _ as *mut c_void,
                &mut yp as *mut _ as *mut c_void,
                &mut mi as *mut _ as *mut c_void,
                &mut ki as *mut _ as *mut c_void,
                &mut ni as *mut _ as *mut c_void,
            ];
            launch_params_blob!(
                self,
                KERNEL,
                [m as u32, take as u32, 1],
                [32, 1, 1],
                0,
                params; wp, xp, yp, mi, ki, ni
            )?;
        }
        Ok(())
    }
    /// Row-tiled BF16-weight x F32 GEMM: `Y[N,M] = X[N,K] @ W[M,K]^T`, same
    /// layout and bit-identical per-output arithmetic as
    /// [`Self::gemm_bf16_xf32_batched`] (and so as [`Self::gemm_f32_batched`]
    /// on the widened weight), but a 256-thread block owns 4 rows with X staged
    /// in LDS, its 8 waves partitioning the outputs.
    pub fn gemm_bf16_xf32_tiled_rows(
        &mut self,
        weight: &GpuTensor,
        x: &GpuTensor,
        y: &GpuTensor,
        m: usize,
        k: usize,
        n: usize,
    ) -> HipResult<()> {
        const NT: usize = 4;
        if m == 0 || n == 0 {
            return Ok(());
        }
        Self::bf16_xf32_check(weight, x, y, m, k, n)?;
        self.bind_thread()?;
        // Wave count 8; MPW=4 serves M <= 32, MPW=16 any M (grid.x over 128).
        let (kname, grid_x) = if m <= 32 {
            ("gemm_bf16_xf32_tiled_rows_mp4", m.div_ceil(32))
        } else {
            ("gemm_bf16_xf32_tiled_rows", m.div_ceil(128))
        };
        // Module name is the file so the source compiles once for both symbols.
        self.ensure_kernel(
            "gemm_bf16_xf32_tiled_rows",
            kernels::GEMM_BF16_XF32_TILED_ROWS_SRC,
            kname,
        )?;
        // Chunk the grid-y extent (tile count) at the launch limit.
        let chunk_rows = F32_BATCHED_MAX_GRID_Y * NT;
        let mut off = 0usize;
        while off < n {
            let take = (n - off).min(chunk_rows);
            let mut wp = weight.buf.as_ptr();
            let mut xp = x
                .buf
                .as_ptr()
                .wrapping_byte_add(off * k * std::mem::size_of::<f32>());
            let mut yp = y
                .buf
                .as_ptr()
                .wrapping_byte_add(off * m * std::mem::size_of::<f32>());
            let mut mi = m as i32;
            let mut ki = k as i32;
            let mut ni = take as i32;
            let mut params = [
                &mut wp as *mut _ as *mut c_void,
                &mut xp as *mut _ as *mut c_void,
                &mut yp as *mut _ as *mut c_void,
                &mut mi as *mut _ as *mut c_void,
                &mut ki as *mut _ as *mut c_void,
                &mut ni as *mut _ as *mut c_void,
            ];
            launch_params_blob!(
                self,
                kname,
                [grid_x as u32, take.div_ceil(NT) as u32, 1],
                [256, 1, 1],
                0,
                params; wp, xp, yp, mi, ki, ni
            )?;
            off += take;
        }
        Ok(())
    }

    /// Whether the Qwen4 F16 WMMA route applies to a `[M × K]` BF16 weight at
    /// `batch_size` rows: gfx11 WMMA or gfx1201 ([`qwen4_f16_shadow_capable`]),
    /// >= QWEN4_F16_WMMA_MIN_TOKENS rows, K % 64 == 0, no recorder/capture
    /// active, not opted out. The placement census charges the lazy F16
    /// shadows this route creates from the same capability predicate
    /// ([`Gpu::qwen4_f16_shadow_capable`]).
    pub fn qwen4_f16_wmma_applies(&self, weight: &GpuTensor, k: usize, batch_size: usize) -> bool {
        qwen4_f16_wmma_applies_for(
            &self.arch_caps,
            *QWEN4_F16_WMMA_GFX1201,
            weight.dtype == DType::BF16,
            self.route_rows(batch_size),
            k,
            !self.replay.is_recording() && !self.graphs.capture_mode,
            *QWEN4_F16_WMMA,
        )
    }

    /// The device's capability half of [`Self::qwen4_f16_wmma_applies`]
    /// ([`qwen4_f16_shadow_capable`] with the gfx1201 opt-in knob): whether
    /// this device can ever create the model-lifetime BF16 -> F16 weight
    /// shadows. The placement census reads exactly this.
    pub fn qwen4_f16_shadow_capable(&self) -> bool {
        qwen4_f16_shadow_capable(&self.arch_caps, *QWEN4_F16_WMMA_GFX1201)
    }

    /// gfx1201 runs the Qwen4 F16 WMMA route on its own gfx12 kernels
    /// (`gemm_f16_x_f16_wmma_lds_splitk.hip`, `hyper_read_up_wmma.gfx1201.hip`)
    /// unless `HIPFIRE_QWEN4_F16_WMMA_GFX1201=0` (default on).
    /// Exact arch: gfx1200 and every other RDNA4 part stay on the multirow arms.
    pub fn qwen4_f16_wmma_gfx1201(&self) -> bool {
        self.arch_caps.is_gfx1201() && *QWEN4_F16_WMMA_GFX1201
    }

    /// Whether a Qwen4 forward of `rows` tokens keeps its HC residual streams as
    /// BF16 bits (the F16 prefill route: gfx11+ ISA, >= QWEN4_F16_WMMA_MIN_TOKENS
    /// rows, no recorder or capture, not opted out).  Every HC reader rounds
    /// the stream to BF16 on load, so the stored value is the one it uses;
    /// the forward decides once and hands the flag to every stream op.
    pub fn qwen4_bf16_streams(&self, rows: usize) -> bool {
        self.arch_caps.has_gfx11_plus_simt()
            && self.route_rows(rows) >= QWEN4_F16_WMMA_MIN_TOKENS
            && !self.replay.is_recording()
            && !self.graphs.capture_mode
            && *QWEN4_F16_WMMA
    }

    /// The shared FP16 activation scratch as an `elems`-long F16 view, for a
    /// producer that writes the F16 WMMA input itself.  Valid until the next
    /// FP16 conversion.  Growth frees the old buffer, so it invalidates
    /// captured graphs / PM4 tapes first, like `ensure_fp16_x`.
    pub fn qwen4_f16_x_scratch(&mut self, elems: usize) -> HipResult<GpuTensor> {
        if crate::scratch::scratch_will_grow(
            self.scratch.fp16_x_scratch_bytes,
            self.scratch.fp16_x_scratch.is_some(),
            elems * 2,
        ) {
            self.invalidate_for_scratch_growth();
        }
        let ptr = self.scratch.fp16_x_scratch_writable(&self.hip, elems)?;
        Ok(GpuTensor {
            buf: unsafe { DeviceBuffer::from_raw(ptr, elems * 2) },
            shape: vec![elems],
            dtype: DType::F16,
        })
    }

    /// `x` (F32, `[n_elems]`) as its F16 conversion (the uncached `convert_f32_to_f16`
    /// launch the F16 WMMA GEMMs of F32 operands issue ahead of themselves) in the
    /// shared F16 scratch, as an F16 view. Valid until the next conversion. The
    /// byte oracle of the fused shared gate/up (`examples/qwen4_shared_gu_pm.rs`)
    /// uses it to launch the chain's own conversion.
    pub fn qwen4_convert_f16_x(&mut self, x: &GpuTensor, n_elems: usize) -> HipResult<GpuTensor> {
        let ptr = self.convert_fp16_x_uncached(x, n_elems)?;
        Ok(GpuTensor {
            buf: unsafe { DeviceBuffer::from_raw(ptr, n_elems * 2) },
            shape: vec![n_elems],
            dtype: DType::F16,
        })
    }

    /// The F16 `[n_elems]` input of a Qwen4 F16 WMMA GEMM: `x` itself when its
    /// producer already left it as F16 (the fused shared gate/up's hidden,
    /// [`Gpu::gemm_bf16_xf32_f16_wmma_qwen4_shared_gu_pm`]), else the
    /// (uncached) F32 -> F16 conversion of `x` in the shared F16 scratch. The
    /// choice is the tensor's dtype: no hidden state.
    pub(crate) fn f16_x_or_convert(
        &mut self,
        x: &GpuTensor,
        n_elems: usize,
    ) -> HipResult<*mut c_void> {
        if x.dtype == DType::F16 {
            assert!(
                x.numel() >= n_elems,
                "F16 GEMM input holds {} of {n_elems} elements",
                x.numel()
            );
            return Ok(x.buf.as_ptr());
        }
        self.convert_fp16_x_uncached(x, n_elems)
    }

    /// Whether the fused shared-expert gate/up kernel
    /// ([`Gpu::gemm_bf16_xf32_f16_wmma_qwen4_shared_gu_pm`]) applies to the BF16
    /// `[m × k]` gate and up weights at `batch_size` rows: exact gfx1151,
    /// `HIPFIRE_QWEN4_SHARED_GU_PM` on (default), both weights on the Qwen4
    /// F16 WMMA route (the chain's own GEMM: >= `QWEN4_F16_WMMA_MIN_TOKENS`
    /// rows, no recorder or capture) and the kernel's shape limits
    /// ([`qwen4_shared_gu_pm_shape`]).
    pub fn qwen4_shared_gu_pm_applies(
        &self,
        gate: &GpuTensor,
        up: &GpuTensor,
        m: usize,
        k: usize,
        batch_size: usize,
    ) -> bool {
        *QWEN4_SHARED_GU_PM
            && self.arch_caps.is_gfx1151()
            && qwen4_shared_gu_pm_shape(m, k, batch_size)
            && self.qwen4_f16_wmma_applies(gate, k, batch_size)
            && self.qwen4_f16_wmma_applies(up, k, batch_size)
    }

    /// One launch of the certified shared gate/up module's entry `wr` (4 or 8 waves
    /// of 16 channels): `hidden` (F16 `[batch_size, m]`) and the in-place
    /// post-sigmoid `selector` (F32 `[batch_size]`) from F16 `x16` (`[batch_size, k]`) and the
    /// BF16 `gate` / `up` weights' F16 shadows, bitwise what the chain of the gate GEMM, the up
    /// GEMM, `shared_expert_activation_bf16_f32` and the F32 -> F16 conversion of the hidden
    /// leaves. The caller gates with [`Gpu::qwen4_shared_gu_pm_applies`].
    #[allow(clippy::too_many_arguments)]
    pub fn qwen4_shared_gu_pm_launch(
        &mut self,
        wr: u8,
        gate: &GpuTensor,
        up: &GpuTensor,
        x16: &GpuTensor,
        hidden: &GpuTensor,
        selector: &GpuTensor,
        m: usize,
        k: usize,
        batch_size: usize,
    ) -> HipResult<()> {
        assert!(
            matches!(wr, 4 | 8),
            "shared gate/up PM entries are w4 and w8"
        );
        assert!(
            qwen4_shared_gu_pm_shape(m, k, batch_size),
            "shared gate/up PM shape {m}x{k}x{batch_size}"
        );
        assert_eq!(
            (x16.dtype, hidden.dtype, selector.dtype),
            (DType::F16, DType::F16, DType::F32)
        );
        assert!(
            x16.numel() >= batch_size * k
                && hidden.numel() >= batch_size * m
                && selector.numel() >= batch_size
        );
        self.bind_thread()?;
        let entry = if wr == 8 {
            "qwen4_shared_gu_pm_gfx1151_w8"
        } else {
            "qwen4_shared_gu_pm_gfx1151_w4"
        };
        let (wg, wu) = (
            self.ensure_bf16_f16_shadow(gate, m, k)?,
            self.ensure_bf16_f16_shadow(up, m, k)?,
        );
        self.ensure_embedded_kernel(
            "qwen4_shared_gu_pm_gfx1151",
            kernels::QWEN4_SHARED_GU_PM_GFX1151,
            entry,
        )?;
        let (mut wgp, mut wup, mut xp) = (wg, wu, x16.buf.as_ptr());
        let (mut yp, mut sp) = (hidden.buf.as_ptr(), selector.buf.as_ptr());
        let (mut mi, mut ki, mut ni) = (m as i32, k as i32, batch_size as i32);
        let mut params: Vec<*mut c_void> = vec![
            &mut wgp as *mut _ as *mut c_void,
            &mut wup as *mut _ as *mut c_void,
            &mut xp as *mut _ as *mut c_void,
            &mut yp as *mut _ as *mut c_void,
            &mut sp as *mut _ as *mut c_void,
            &mut mi as *mut _ as *mut c_void,
            &mut ki as *mut _ as *mut c_void,
            &mut ni as *mut _ as *mut c_void,
        ];
        let grid = [
            m.div_ceil(16 * usize::from(wr)) as u32,
            batch_size.div_ceil(128) as u32,
            1,
        ];
        let bytes = 2 * m * k * 2 + batch_size * k * 2 + batch_size * m * 2 + batch_size * 8;
        let timer = crate::profile::begin_timer(&self.hip, "gemm", entry, bytes);
        let result = self.launch_maybe_blob(
            entry,
            grid,
            [32 * u32::from(wr), 1, 1],
            0,
            &mut params,
            || {
                let mut b = hip_bridge::KernargBlob::new();
                b.push_ptr(wgp);
                b.push_ptr(wup);
                b.push_ptr(xp);
                b.push_ptr(yp);
                b.push_ptr(sp);
                b.push_i32(mi);
                b.push_i32(ki);
                b.push_i32(ni);
                b
            },
        );
        if let Some(t) = timer {
            t.finish(&self.hip);
        }
        result
    }

    /// The Flash-Next shared-expert gate/up in one launch: the router's and the selector's
    /// F16 WMMA GEMMs (the groups `[router]`, `[selector]`, off one F16 conversion of `x`,
    /// exactly as [`Gpu::gemm_bf16_xf32_f16_wmma_qwen4_groups`] launches them), then
    /// [`Gpu::qwen4_shared_gu_pm_launch`] over that conversion in place of the gate and up
    /// GEMMs, the activation and the hidden's conversion. `hidden` is the F16 `[batch_size, m]`
    /// destination (the shared down reads it as its F16 input). `x16`, when given, is the F16
    /// conversion of `x` the fused MoE front already left in the shared F16 scratch
    /// ([`Gpu::qwen4_moe_front_producer`]): no `convert_f32_to_f16` is launched, and nothing may
    /// have converted into that scratch since. Returns `false` with nothing
    /// launched unless the route applies ([`Gpu::qwen4_shared_gu_pm_applies`] and the groups'
    /// own conditions).
    #[allow(clippy::too_many_arguments)]
    pub fn gemm_bf16_xf32_f16_wmma_qwen4_shared_gu_pm(
        &mut self,
        router: (&GpuTensor, &GpuTensor, usize),
        selector: (&GpuTensor, &GpuTensor, usize),
        gate: &GpuTensor,
        up: &GpuTensor,
        hidden: &GpuTensor,
        x: &GpuTensor,
        x16: Option<&GpuTensor>,
        m: usize,
        k: usize,
        batch_size: usize,
    ) -> HipResult<bool> {
        if !self.qwen4_shared_gu_pm_applies(gate, up, m, k, batch_size)
            || !self.gemm_bf16_xf32_f16_wmma_qwen4_groups_x16(
                &[&[router][..], &[selector][..]],
                x,
                x16,
                k,
                batch_size,
            )?
        {
            return Ok(false);
        }
        // Nothing since the groups' conversion (or the front producer's store) wrote the F16
        // scratch: the view is the same bytes.
        let x16 = self.qwen4_f16_x_scratch(batch_size * k)?;
        self.qwen4_shared_gu_pm_launch(
            QWEN4_SHARED_GU_PM_WAVES,
            gate,
            up,
            &x16,
            hidden,
            selector.1,
            m,
            k,
            batch_size,
        )?;
        Ok(true)
    }

    /// Checks shared by the DET dense wrappers and their launch-only hooks: exact gfx1151, shape
    /// limits ([`mtp_dense_det_pm_shape`]), operand dtypes (`weight` of `weight_dtype`: BF16 or
    /// F16 `[m, k]`, or Q8_0 packed 34-byte blocks; `x` of `x_dtype`; `y` F32) and buffer
    /// capacities (a Q8_0 weight needs `m * k / 32 * 34` bytes).
    #[allow(clippy::too_many_arguments)]
    fn mtp_dense_det_pm_validate(
        &self,
        weight: &GpuTensor,
        weight_dtype: DType,
        x: &GpuTensor,
        x_dtype: DType,
        y: &GpuTensor,
        m: usize,
        k: usize,
        n: usize,
    ) -> HipResult<()> {
        let err = |msg: String| hip_bridge::HipError::new(0, &format!("mtp_dense_det_pm: {msg}"));
        if self.arch != "gfx1151" {
            return Err(err(format!(
                "requires exact gfx1151 (device is {})",
                self.arch
            )));
        }
        if !mtp_dense_det_pm_shape(m, k, n) {
            return Err(err(format!(
                "shape M={m} K={k} N={n} outside the kernel's limits (M%16==0, K%64==0, N>=1, extents < 2^31)"
            )));
        }
        if weight.dtype != weight_dtype || x.dtype != x_dtype || y.dtype != DType::F32 {
            return Err(err(format!(
                "dtypes must be weight {weight_dtype:?}, X {x_dtype:?}, Y F32 (got {:?}, {:?}, {:?})",
                weight.dtype, x.dtype, y.dtype
            )));
        }
        let x_elem = if x_dtype == DType::F16 { 2 } else { 4 };
        let weight_bytes = if weight_dtype == DType::Q8_0 {
            m * (k / 32) * 34
        } else {
            m * k * 2
        };
        if weight.buf.size() < weight_bytes
            || x.buf.size() < n * k * x_elem
            || y.buf.size() < n * m * 4
        {
            return Err(err("buffer capacity is too small".into()));
        }
        Ok(())
    }

    /// Launch-only hook of the standalone MTP dense DET GEMM
    /// (`kernels::MTP_DENSE_DET_PM_GFX1151`, entry `mtp_dense_det_pm_gfx1151_w8`): `y` (F32
    /// `[n, m]`) from F16 `x16` (`[n, k]`) and the model-lifetime F16 shadow of the BF16 `weight`
    /// (`[m, k]`; created on first use, keyed by the weight pointer, so the weight must stay
    /// alive). One fixed 128 x 256 tile and one ascending K16 WMMA chain per output, no split-K,
    /// no epilogue; DET, not byte-equal to the BF16 incumbent. No X conversion is issued here.
    /// Errors (nothing launched) outside exact gfx1151 or [`mtp_dense_det_pm_shape`], on a
    /// dtype / capacity mismatch, a pointer not 16-byte aligned, or `y` overlapping an input.
    #[allow(clippy::too_many_arguments)]
    pub fn mtp_dense_det_pm_launch(
        &mut self,
        weight: &GpuTensor,
        x16: &GpuTensor,
        y: &GpuTensor,
        m: usize,
        k: usize,
        n: usize,
    ) -> HipResult<()> {
        self.bind_thread()?;
        self.mtp_dense_det_pm_validate(weight, DType::BF16, x16, DType::F16, y, m, k, n)?;
        let ap = self.ensure_bf16_f16_shadow(weight, m, k)?;
        self.mtp_dense_det_pm_launch_a16(ap, x16, y, m, k, n)
    }

    /// [`Gpu::mtp_dense_det_pm_launch`] for an F16 `weight16` (`[m, k]`, used as A16 directly: no
    /// shadow): the same kernel, entry, ABI and checks, so a row's bytes are those of the BF16 hook
    /// over the same F16 values.
    #[allow(clippy::too_many_arguments)]
    pub fn mtp_dense_det_pm_launch_f16(
        &mut self,
        weight16: &GpuTensor,
        x16: &GpuTensor,
        y: &GpuTensor,
        m: usize,
        k: usize,
        n: usize,
    ) -> HipResult<()> {
        self.bind_thread()?;
        self.mtp_dense_det_pm_validate(weight16, DType::F16, x16, DType::F16, y, m, k, n)?;
        self.mtp_dense_det_pm_launch_a16(weight16.buf.as_ptr(), x16, y, m, k, n)
    }

    /// The one launch of `mtp_dense_det_pm_gfx1151_w8` over a validated F16 A16 device pointer
    /// (an F16 weight or a model-lifetime shadow): 16-byte alignment, `y` non-overlap, grid and
    /// kernarg. Callers validate dtypes, shape and capacities first.
    #[allow(clippy::too_many_arguments)]
    fn mtp_dense_det_pm_launch_a16(
        &mut self,
        mut ap: *mut c_void,
        x16: &GpuTensor,
        y: &GpuTensor,
        m: usize,
        k: usize,
        n: usize,
    ) -> HipResult<()> {
        let err = |msg: String| hip_bridge::HipError::new(0, &format!("mtp_dense_det_pm: {msg}"));
        let (mut xp, mut yp) = (x16.buf.as_ptr(), y.buf.as_ptr());
        let (a_lo, x_lo, y_lo) = (ap as usize, xp as usize, yp as usize);
        if a_lo % 16 != 0 || x_lo % 16 != 0 || y_lo % 16 != 0 {
            return Err(err("A16, X16 and Y must be 16-byte aligned".into()));
        }
        let overlaps = |lo: usize, len: usize| y_lo < lo + len && lo < y_lo + n * m * 4;
        if overlaps(a_lo, m * k * 2) || overlaps(x_lo, n * k * 2) {
            return Err(err("Y overlaps an input".into()));
        }
        self.ensure_embedded_kernel(
            "mtp_dense_det_pm_gfx1151",
            kernels::MTP_DENSE_DET_PM_GFX1151,
            MTP_DENSE_DET_PM_ENTRY,
        )?;
        let (mut mi, mut ki, mut ni) = (m as i32, k as i32, n as i32);
        let mut params: Vec<*mut c_void> = vec![
            &mut ap as *mut _ as *mut c_void,
            &mut xp as *mut _ as *mut c_void,
            &mut yp as *mut _ as *mut c_void,
            &mut mi as *mut _ as *mut c_void,
            &mut ki as *mut _ as *mut c_void,
            &mut ni as *mut _ as *mut c_void,
        ];
        let grid = [
            m.div_ceil(MTP_DENSE_DET_PM_TILE_M) as u32,
            n.div_ceil(MTP_DENSE_DET_PM_TILE_N) as u32,
            1,
        ];
        let bytes = m * k * 2 + n * k * 2 + n * m * 4;
        let timer = crate::profile::begin_timer(&self.hip, "gemm", MTP_DENSE_DET_PM_ENTRY, bytes);
        let result = self.launch_maybe_blob(
            MTP_DENSE_DET_PM_ENTRY,
            grid,
            [256, 1, 1],
            0,
            &mut params,
            || {
                let mut b = hip_bridge::KernargBlob::new();
                b.push_ptr(ap);
                b.push_ptr(xp);
                b.push_ptr(yp);
                b.push_i32(mi);
                b.push_i32(ki);
                b.push_i32(ni);
                b
            },
        );
        if let Some(t) = timer {
            t.finish(&self.hip);
        }
        result
    }

    /// Standalone MTP dense DET projection `Y[n, m] = Σ_k W[m, k]·X[n, k]` for a BF16 weight and
    /// F32 X / Y, directly callable at any `n >= 1` (fc_hidden: `m = k = 2560`). Warms the
    /// weight's model-lifetime F16 shadow (BF16 -> F32 exact widening -> F16 RNE, once), converts
    /// X F32 -> F16 RNE uncached on every call, then launches
    /// [`Gpu::mtp_dense_det_pm_launch`] on the same stream: each output is one ascending K16 WMMA
    /// chain from +0 whatever `n` is, so a row's bytes do not depend on its batch. F16 has a
    /// narrower exponent range than BF16/F32: under/overflow is possible and this is explicitly
    /// DET, not byte-equal to [`Gpu::gemm_bf16_xf32_multirow`]. Called by the
    /// `HIPFIRE_QWEN4_MTP_APPEND_DET` prompt-fill append route (default on, exact gfx1151;
    /// fc_embedding, fc_hidden, HC up).
    #[allow(clippy::too_many_arguments)]
    pub fn gemm_bf16_xf32_mtp_dense_det_pm(
        &mut self,
        weight: &GpuTensor,
        x: &GpuTensor,
        y: &GpuTensor,
        m: usize,
        k: usize,
        n: usize,
    ) -> HipResult<()> {
        self.bind_thread()?;
        self.mtp_dense_det_pm_validate(weight, DType::BF16, x, DType::F32, y, m, k, n)?;
        let x16 = self.qwen4_convert_f16_x(x, n * k)?;
        self.mtp_dense_det_pm_launch(weight, &x16, y, m, k, n)
    }

    /// The model-lifetime F16 shadow of the BF16 `[m, k]` `weight` (created on first use,
    /// keyed by the weight pointer) as a non-owning F16 `[m*k]` view: what
    /// [`Gpu::mtp_dense_det_pm_launch`] reads as A16, for the standalone DET harness's oracle
    /// and conversion checks. Do not free the view; keep `weight` alive.
    pub fn mtp_dense_det_pm_weight_shadow(
        &mut self,
        weight: &GpuTensor,
        m: usize,
        k: usize,
    ) -> HipResult<GpuTensor> {
        self.bind_thread()?;
        if weight.dtype != DType::BF16 || m == 0 || k == 0 || weight.buf.size() < m * k * 2 {
            return Err(hip_bridge::HipError::new(
                0,
                "mtp_dense_det_pm_weight_shadow: needs a BF16 weight of at least m*k elements",
            ));
        }
        let ptr = self.ensure_bf16_f16_shadow(weight, m, k)?;
        Ok(GpuTensor {
            buf: unsafe { DeviceBuffer::from_raw(ptr, m * k * 2) },
            shape: vec![m * k],
            dtype: DType::F16,
        })
    }

    /// Standalone MTP dense DET projection `Y[n, m] = Σ_k W[m, k]·X[n, k]` for a Q8_0 weight (packed
    /// 34-byte blocks, contiguous `[m, k]`) and F32 X / Y: [`Gpu::gemm_bf16_xf32_mtp_dense_det_pm`]'s
    /// kernel and tile with the weight read from its model-lifetime F16 shadow
    /// ([`Gpu::ensure_q8_0_f16_shadow`]: element `F16-RNE(f32(scale) * f32(q))`, created on first
    /// use, keyed by the weight pointer, so the weight must stay alive). X F32 -> F16 RNE is
    /// converted uncached on every call; each output is one ascending K16 WMMA chain from +0
    /// whatever `n` is, so a row's bytes do not depend on its batch. Shapes as
    /// [`mtp_dense_det_pm_shape`] (`m % 16 == 0`, `k % 64 == 0`, `n >= 1`). DET, not byte-equal to
    /// the staged Q8_0 GEMV: F16 operands narrow the exponent range (under/overflow of either
    /// the converted weight or X is possible).
    #[allow(clippy::too_many_arguments)]
    pub fn gemm_q8_0_xf32_mtp_dense_det_pm(
        &mut self,
        weight: &GpuTensor,
        x: &GpuTensor,
        y: &GpuTensor,
        m: usize,
        k: usize,
        n: usize,
    ) -> HipResult<()> {
        self.bind_thread()?;
        self.mtp_dense_det_pm_validate(weight, DType::Q8_0, x, DType::F32, y, m, k, n)?;
        let x16 = self.qwen4_convert_f16_x(x, n * k)?;
        self.mtp_q8_det_pm_launch(weight, &x16, y, m, k, n)
    }

    /// Launch-only hook of the Q8_0 MTP dense DET GEMM, the Q8_0 analogue of
    /// [`Gpu::mtp_dense_det_pm_launch`]: `y` (F32 `[n, m]`) from F16 `x16` (`[n, k]`) and the
    /// model-lifetime F16 shadow of the Q8_0 `weight` ([`Gpu::ensure_q8_0_f16_shadow`], created on
    /// first use, keyed by the weight pointer, so the weight must stay alive), then the one
    /// dense launch. No X conversion is issued here, so one converted `x16` can feed several
    /// projections of the same input. The shadow converter writes its own immutable tensor and
    /// never touches the shared F16 X scratch, so `x16` may be converted before the weight's first
    /// (lazy) shadow on the same stream. Errors (nothing launched) as the BF16 hook.
    #[allow(clippy::too_many_arguments)]
    pub fn mtp_q8_det_pm_launch(
        &mut self,
        weight: &GpuTensor,
        x16: &GpuTensor,
        y: &GpuTensor,
        m: usize,
        k: usize,
        n: usize,
    ) -> HipResult<()> {
        self.bind_thread()?;
        self.mtp_dense_det_pm_validate(weight, DType::Q8_0, x16, DType::F16, y, m, k, n)?;
        let ap = self.ensure_q8_0_f16_shadow(weight, m, k)?;
        self.mtp_dense_det_pm_launch_a16(ap, x16, y, m, k, n)
    }

    /// The model-lifetime F16 shadow of the Q8_0 `[m, k]` `weight` (created on first use, keyed
    /// by the weight pointer) as a non-owning F16 `[m*k]` view: what
    /// [`Gpu::gemm_q8_0_xf32_mtp_dense_det_pm`] reads as A16, for the DET harness's conversion
    /// checks. Do not free the view; keep `weight` alive.
    pub fn mtp_q8_det_pm_weight_shadow(
        &mut self,
        weight: &GpuTensor,
        m: usize,
        k: usize,
    ) -> HipResult<GpuTensor> {
        self.bind_thread()?;
        let ptr = self.ensure_q8_0_f16_shadow(weight, m, k)?;
        Ok(GpuTensor {
            buf: unsafe { DeviceBuffer::from_raw(ptr, m * k * 2) },
            shape: vec![m * k],
            dtype: DType::F16,
        })
    }

    /// Whether [`Gpu::gemm_bf16_xf16_hc_down_fused`] replaces the HC-down GEMM +
    /// activation chain for this shape (see [`hc_down_fused_selected`]).
    pub fn qwen4_hc_down_fused_applies(&self, m: usize, k: usize, rows: usize) -> bool {
        hc_down_fused_selected(
            self.arch.as_str(),
            *QWEN4_HC_DOWN_FUSED,
            m,
            k,
            self.route_rows(rows),
            self.replay.is_recording(),
            self.graphs.capture_mode,
        )
    }

    /// gfx1201 / gfx1151 HC-down (BF16 `weight` [m, k] on its F16 shadow, F16 `x_f16` [rows, k])
    /// fused with `hc_activation_fused_f32`: writes only the packed BF16 activation `low_bf16`
    /// [rows, m], byte-identical to `gemm_bf16_xf16_f16_wmma` + `hc_activation_fused_f32(bf16_out)`
    /// on the same arch. Callers gate on [`Gpu::qwen4_hc_down_fused_applies`].
    #[allow(clippy::too_many_arguments)]
    pub fn gemm_bf16_xf16_hc_down_fused(
        &mut self,
        weight: &GpuTensor,
        x_f16: &GpuTensor,
        low_bf16: &GpuTensor,
        m: usize,
        k: usize,
        batch_size: usize,
        scale: f32,
    ) -> HipResult<()> {
        self.bind_thread()?;
        assert!(
            matches!(self.arch.as_str(), "gfx1201" | "gfx1151") && m == 320 && k == 10240,
            "gemm_bf16_xf16_hc_down_fused: gfx1201/gfx1151 M=320 K=10240 only (arch {}, m {m}, k {k})",
            self.arch
        );
        assert!(
            weight.dtype == DType::BF16
                && x_f16.dtype == DType::F16
                && low_bf16.dtype == DType::BF16,
            "gemm_bf16_xf16_hc_down_fused: dtypes must be BF16 weight, F16 x, BF16 out"
        );
        assert!(
            weight.numel() >= m * k
                && x_f16.numel() >= batch_size * k
                && low_bf16.numel() >= batch_size * m
                && batch_size * k * 2 < (1usize << 32),
            "gemm_bf16_xf16_hc_down_fused: operands too small or too large for [{m} x {k}] x {batch_size}"
        );
        if batch_size == 0 {
            return Ok(());
        }
        let w16 = self.ensure_bf16_f16_shadow(weight, m, k)?;
        let xp = x_f16.buf.as_ptr();
        let op = low_bf16.buf.as_ptr();
        assert!(
            (w16 as usize) % 16 == 0 && (xp as usize) % 16 == 0 && (op as usize) % 16 == 0,
            "gemm_bf16_xf16_hc_down_fused: operands must be 16-byte aligned"
        );
        // (module, source, entry, tokens per workgroup, threads per workgroup): gfx1151 runs
        // five 64-row M waves over 32 tokens, gfx1201 four 80-row waves over 64.
        let (module, src, entry, tile_rows, threads): (&str, &str, &str, usize, u32) =
            if self.arch == "gfx1151" {
                (
                    "qwen4_hc_down_fused_gfx1151",
                    kernels::QWEN4_HC_DOWN_FUSED_GFX1151_SRC,
                    "qwen4_hc_down_fused_gfx1151",
                    32,
                    160,
                )
            } else {
                (
                    "qwen4_hc_down_fused",
                    kernels::QWEN4_HC_DOWN_FUSED_SRC,
                    "qwen4_hc_down_fused_b64_k32",
                    64,
                    256,
                )
            };
        self.ensure_kernel(module, src, entry)?;
        let ap = w16;
        let ki = k as i32;
        let bi = batch_size as i32;
        let mut params: Vec<*mut c_void> = vec![
            &ap as *const _ as *mut c_void,
            &xp as *const _ as *mut c_void,
            &op as *const _ as *mut c_void,
            &ki as *const _ as *mut c_void,
            &bi as *const _ as *mut c_void,
            &scale as *const _ as *mut c_void,
        ];
        self.launch_maybe_blob(
            entry,
            [batch_size.div_ceil(tile_rows) as u32, 1, 1],
            [threads, 1, 1],
            0,
            &mut params,
            || {
                let mut b = hip_bridge::KernargBlob::new();
                b.push_ptr(ap);
                b.push_ptr(xp);
                b.push_ptr(op);
                b.push_i32(ki);
                b.push_i32(bi);
                b.push_f32(scale);
                b
            },
        )
    }

    /// `Y[b, m] = Σ_k W[m, k]·X[b, k]` for a BF16 weight through a
    /// model-lifetime F16 shadow and the LDS-staged F16 WMMA GEMM, X already
    /// F16.  2.5-5x the BF16 multirow kernel on gfx1151, 4-30x on gfx1201.
    /// Not bit-exact: callers are KLD-gated (see [`Gpu::qwen4_f16_wmma_applies`]).
    #[allow(clippy::too_many_arguments)]
    pub fn gemm_bf16_xf16_f16_wmma(
        &mut self,
        weight: &GpuTensor,
        x_f16: &GpuTensor,
        y: &GpuTensor,
        m: usize,
        k: usize,
        batch_size: usize,
    ) -> HipResult<()> {
        self.bind_thread()?;
        if *QWEN4_PROJ_REGIONS
            && m == 320 && k == 10240
            // gfx1201's incumbent HC-down is split-K=4, not ascending K.
            && self.arch_caps.has_wmma_w32()
        {
            return self.gemm_bf16_xf16_f16_wmma_regions(&[(weight, y, m)], x_f16, k, batch_size);
        }
        let w16 = self.ensure_bf16_f16_shadow(weight, m, k)?;
        let w_view = GpuTensor {
            buf: unsafe { DeviceBuffer::from_raw(w16, m * k * 2) },
            shape: vec![m * k],
            dtype: DType::F16,
        };
        if self.arch_caps.is_gfx1201() {
            // HC-down keeps the incumbent 64 x 128 p_s4 tile's four K splits on the
            // 160 x 80 / k32 tile (HIPFIRE_QWEN4_HC_DOWN_TILE), so the bytes match.
            let tile = if hc_down_tile_selected(
                self.arch.as_str(),
                *QWEN4_HC_DOWN_TILE,
                m,
                k,
                self.route_rows(batch_size),
                self.replay.is_recording(),
                self.graphs.capture_mode,
            ) {
                LdsTileSplitK::HC_DOWN_GFX1201
            } else {
                Self::qwen4_lds_tile_gfx1201(m, k)
            };
            return self.gemm_f16_x_f16_wmma_lds_splitk(&w_view, x_f16, y, m, k, batch_size, tile);
        }
        // Measured gfx1151 (flushed, N = 8192 / 2048 / 512): 3.66 / 1.75 / 0.60 ms on 64 x 64
        // vs 3.10 / 1.54 / 1.12 ms on 160 x 64, so only the large batches take it.
        if hc_down_tile_selected(
            self.arch.as_str(),
            *QWEN4_HC_DOWN_TILE,
            m,
            k,
            self.route_rows(batch_size),
            self.replay.is_recording(),
            self.graphs.capture_mode,
        ) {
            return self.gemm_f16_x_f16_wmma_lds_tiled_ld(
                &w_view,
                x_f16,
                y,
                None,
                m,
                k,
                batch_size,
                LdsTile::new(160, 64, 32, 64, 64, false).pipelined(),
                k,
                k,
            );
        }
        // M < 512 (HC input_mix_down 320 x 10240, the shared-expert selector
        // 1 x 2560): the auto tile gives too few workgroups; 64 x 64 keeps
        // each output's K order.  M < 1024 (router 512, shared gate/up 640 at
        // K 2560): 128 x 128 over 128 x 256, 175 vs 213 us at 640 x 2560 x 1131;
        // every tile keeps each output's K order.
        if hc_mix_fill80_gfx1100_selected(
            self.arch.as_str(),
            self.flags.qwen4_hc_mix_fill80_gfx1100_enabled(),
            m,
            k,
        ) {
            return self.gemm_f16_x_f16_wmma_lds_tiled_ld(
                &w_view,
                x_f16,
                y,
                None,
                m,
                k,
                batch_size,
                LdsTile::HC_MIX_FILL80_GFX1100,
                k,
                k,
            );
        }
        let tile = match m {
            0..512 => LdsTile::new(64, 64, 32, 64, 64, false),
            512..1024 => LdsTile::new(128, 128, 32, 64, 64, false),
            _ => {
                return self.gemm_f16_x_f16_wmma_lds_auto(&w_view, x_f16, y, None, m, k, batch_size)
            }
        };
        self.gemm_f16_x_f16_wmma_lds_tiled_ld(
            &w_view,
            x_f16,
            y,
            None,
            m,
            k,
            batch_size,
            tile.pipelined(),
            k,
            k,
        )
    }

    /// Virtually concatenated BF16 shadows, with ascending 16-element K steps.
    /// Up to four matrices share one X tile; zero-row regions are skipped.
    pub fn gemm_bf16_xf16_f16_wmma_regions(
        &mut self,
        projections: &[(&GpuTensor, &GpuTensor, usize)],
        x_f16: &GpuTensor,
        k: usize,
        batch_size: usize,
    ) -> HipResult<()> {
        assert!(!projections.is_empty() && projections.len() <= 4);
        assert!(k > 0 && k % 64 == 0);
        assert_eq!(x_f16.dtype, DType::F16);
        if batch_size == 0 || projections.iter().all(|p| p.2 == 0) {
            return Ok(());
        }
        self.bind_thread()?;
        let mut ap = [std::ptr::null_mut(); 4];
        let mut yp = [std::ptr::null_mut(); 4];
        let mut ms = [0i32; 4];
        for (i, &(weight, y, m)) in projections.iter().enumerate() {
            assert_eq!(weight.dtype, DType::BF16);
            assert_eq!(y.dtype, DType::F32);
            if m != 0 {
                ap[i] = self.ensure_bf16_f16_shadow(weight, m, k)?;
            }
            yp[i] = y.buf.as_ptr();
            ms[i] = i32::try_from(m).expect("region rows fit i32");
        }
        let entry = "gemm_f16_x_f16_wmma_lds_regions_128_128_32_64_k64_p";
        self.ensure_kernel(
            "qwen4_gemm_wmma_lds256",
            kernels::QWEN4_GEMM_F16_X_F16_WMMA_LDS256_SRC,
            entry,
        )?;
        let xp = x_f16.buf.as_ptr();
        let ki = i32::try_from(k).expect("K fits i32");
        let ni = i32::try_from(batch_size).expect("batch fits i32");
        let mut params: [*mut c_void; 17] = std::array::from_fn(|i| match i {
            0..=3 => &ap[i] as *const _ as *mut c_void,
            4 => &xp as *const _ as *mut c_void,
            5..=8 => &yp[i - 5] as *const _ as *mut c_void,
            9..=12 => &ms[i - 9] as *const _ as *mut c_void,
            14 => &ni as *const _ as *mut c_void,
            _ => &ki as *const _ as *mut c_void,
        });
        let total: usize = projections.iter().map(|p| p.2).sum();
        self.launch_maybe_blob(
            entry,
            [
                total.div_ceil(128) as u32,
                batch_size.div_ceil(128) as u32,
                1,
            ],
            [256, 1, 1],
            0,
            &mut params,
            || {
                let mut b = hip_bridge::KernargBlob::new();
                for p in ap {
                    b.push_ptr(p);
                }
                b.push_ptr(xp);
                for p in yp {
                    b.push_ptr(p);
                }
                for m in ms {
                    b.push_i32(m);
                }
                b.push_i32(ki);
                b.push_i32(ni);
                b.push_i32(ki);
                b.push_i32(ki);
                b
            },
        )
    }

    /// [`Gpu::gemm_bf16_xf16_f16_wmma`] from F32 X for each `(weight, y, m)`
    /// (all reading the same `[batch_size, k]` X, converted to F16 once) when
    /// the route applies to every weight; returns `false` with nothing
    /// launched otherwise.  On gfx1201 a projection shorter than one 16-row
    /// WMMA tile (the M = 4 hyper-write gate, the M = 1 selector) runs the
    /// exact multirow kernel instead: with the F16 conversion of X paid it
    /// loses there (4 x 20480 x 1536: 0.432 vs 0.207 ms; 4 x 10240 x 1900:
    /// 0.255 vs 0.091 ms).
    pub fn gemm_bf16_xf32_f16_wmma_qwen4(
        &mut self,
        projections: &[(&GpuTensor, &GpuTensor, usize)],
        x: &GpuTensor,
        k: usize,
        batch_size: usize,
    ) -> HipResult<bool> {
        self.gemm_bf16_xf32_f16_wmma_qwen4_groups(&[projections], x, k, batch_size)
    }

    /// [`Gpu::gemm_bf16_xf32_f16_wmma_qwen4`] for several projection groups
    /// reading the same X, converted to F16 once for all of them: each group
    /// launches exactly what its own call would (the opt-in region fold is
    /// still decided per group), in group order, so every output's bytes are
    /// unchanged.  Returns `false` with nothing launched unless the route
    /// applies to every weight of every group.
    pub fn gemm_bf16_xf32_f16_wmma_qwen4_groups(
        &mut self,
        groups: &[&[(&GpuTensor, &GpuTensor, usize)]],
        x: &GpuTensor,
        k: usize,
        batch_size: usize,
    ) -> HipResult<bool> {
        self.gemm_bf16_xf32_f16_wmma_qwen4_groups_x16(groups, x, None, k, batch_size)
    }

    /// [`Gpu::gemm_bf16_xf32_f16_wmma_qwen4_groups`] with `x16`, when given, being the F16
    /// conversion of `x` already in place (the fused MoE front,
    /// [`Gpu::qwen4_moe_front_producer`]): no `convert_f32_to_f16` is launched and every GEMM
    /// reads `x16` exactly as it reads the conversion's output (the short M < 16 projections
    /// still read the F32 `x`). Nothing may have converted into the F16 scratch since `x16`
    /// was produced.
    pub fn gemm_bf16_xf32_f16_wmma_qwen4_groups_x16(
        &mut self,
        groups: &[&[(&GpuTensor, &GpuTensor, usize)]],
        x: &GpuTensor,
        x16: Option<&GpuTensor>,
        k: usize,
        batch_size: usize,
    ) -> HipResult<bool> {
        if groups.iter().any(|g| g.is_empty())
            || !groups
                .iter()
                .flat_map(|g| g.iter())
                .all(|(weight, _, _)| self.qwen4_f16_wmma_applies(weight, k, batch_size))
        {
            return Ok(false);
        }
        self.bind_thread()?;
        let gfx1201 = self.arch_caps.is_gfx1201();
        let short = move |m: usize| m < 16 && gfx1201;
        if let Some(t) = x16 {
            if t.dtype != DType::F16 || t.numel() < batch_size * k {
                return Err(hip_bridge::HipError::new(
                    0,
                    "gemm_bf16_xf32_f16_wmma_qwen4_groups_x16: x16 must be F16 with batch * k elements",
                ));
            }
        }
        let mut x_view: Option<GpuTensor> = x16.map(GpuTensor::shallow_clone);
        for projections in groups {
            for &(weight, y, m) in projections.iter().filter(|&&(_, _, m)| short(m)) {
                self.gemm_bf16_xf32_multirow(weight, x, y, m, k, batch_size)?;
            }
            if projections.iter().all(|&(_, _, m)| short(m)) {
                continue;
            }
            // Nothing between the groups writes X or the F16 scratch.
            if x_view.is_none() {
                let x16 = self.convert_fp16_x_uncached(x, batch_size * k)?;
                x_view = Some(GpuTensor {
                    buf: unsafe { DeviceBuffer::from_raw(x16, batch_size * k * 2) },
                    shape: vec![batch_size * k],
                    dtype: DType::F16,
                });
            }
            let x_view = x_view.as_ref().unwrap();
            if *QWEN4_PROJ_REGIONS
                && k == 2560
                && projections.len() > 1
                && projections.iter().all(|p| matches!(p.2, 1 | 512 | 640))
                && (self.arch_caps.has_wmma_w32() || self.arch_caps.is_gfx1201())
            {
                let mut group = [projections[0]; 4];
                let mut count = 0;
                for &p in projections.iter().filter(|&&(_, _, m)| !short(m)) {
                    group[count] = p;
                    count += 1;
                    if count == 4 {
                        self.gemm_bf16_xf16_f16_wmma_regions(&group, x_view, k, batch_size)?;
                        count = 0;
                    }
                }
                if count != 0 {
                    self.gemm_bf16_xf16_f16_wmma_regions(&group[..count], x_view, k, batch_size)?;
                }
                continue;
            }
            for &(weight, y, m) in projections.iter().filter(|&&(_, _, m)| !short(m)) {
                self.gemm_bf16_xf16_f16_wmma(weight, x_view, y, m, k, batch_size)?;
            }
        }
        Ok(true)
    }
    /// Whether `HIPFIRE_QWEN4_SHARED_DOWN_EPI` (developer, default off) lets
    /// [`Gpu::qwen4_shared_down_bf16_epi`] take the shared down: the gfx1201 HC row
    /// fold reproduces the generic shared down + scaled add and declines when it is on.
    pub fn qwen4_shared_down_epi_enabled(&self) -> bool {
        *QWEN4_SHARED_DOWN_EPI
    }
    /// Opt-in shared-down fusion; retains the incumbent WMMA accumulation order.
    /// Returns false without launching when the existing F16 route is unavailable.
    pub fn qwen4_shared_down_bf16_epi(
        &mut self,
        weight: &GpuTensor,
        x: &GpuTensor,
        residual: &GpuTensor,
        scalar: &GpuTensor,
        m: usize,
        k: usize,
        rows: usize,
    ) -> HipResult<bool> {
        if !*QWEN4_SHARED_DOWN_EPI || !self.qwen4_f16_wmma_applies(weight, k, rows) || m < 1024 {
            return Ok(false);
        }
        self.bind_thread()?;
        let wp = self.ensure_bf16_f16_shadow(weight, m, k)?;
        let xp = self.f16_x_or_convert(x, rows * k)?;
        if self.arch_caps.is_gfx1201() {
            const ENTRY: &str = "qwen4_wmma_lds_128_256_32_64_k64_bsr";
            self.ensure_kernel(
                "gemm_wmma_lds_splitk",
                kernels::GEMM_F16_X_F16_WMMA_LDS_SPLITK_SRC,
                ENTRY,
            )?;
            assert_eq!(residual.dtype, DType::F32);
            assert_eq!(scalar.dtype, DType::F32);
            assert_eq!(residual.numel(), rows * m);
            assert_eq!(scalar.numel(), rows);
            let rp = residual.buf.as_ptr();
            let sp = scalar.buf.as_ptr();
            let mi = m as i32;
            let ki = k as i32;
            let ni = rows as i32;
            let mut params = [
                &wp as *const _ as *mut c_void,
                &xp as *const _ as *mut c_void,
                &rp as *const _ as *mut c_void,
                &mi as *const _ as *mut c_void,
                &ki as *const _ as *mut c_void,
                &ni as *const _ as *mut c_void,
                &rp as *const _ as *mut c_void,
                &sp as *const _ as *mut c_void,
            ];
            self.launch_maybe_blob(
                ENTRY,
                [m.div_ceil(128) as u32, rows.div_ceil(256) as u32, 1],
                [512, 1, 1],
                0,
                &mut params,
                || {
                    let mut b = hip_bridge::KernargBlob::new();
                    b.push_ptr(wp);
                    b.push_ptr(xp);
                    b.push_ptr(rp);
                    b.push_i32(mi);
                    b.push_i32(ki);
                    b.push_i32(ni);
                    b.push_ptr(rp);
                    b.push_ptr(sp);
                    b
                },
            )?;
            return Ok(true);
        }
        let w = GpuTensor {
            buf: unsafe { DeviceBuffer::from_raw(wp, m * k * 2) },
            shape: vec![m * k],
            dtype: DType::F16,
        };
        let xv = GpuTensor {
            buf: unsafe { DeviceBuffer::from_raw(xp, rows * k * 2) },
            shape: vec![rows * k],
            dtype: DType::F16,
        };
        let epi = GemmEpilogue {
            gate: Some(scalar),
            residual: Some(residual),
            bf16_scaled_add: true,
            ..Default::default()
        };
        self.gemm_f16_x_f16_wmma_lds_auto_epi(&w, &xv, residual, None, m, k, rows, &epi)?;
        Ok(true)
    }

    /// Whether [`Gpu::gemm_bf16_xf32_f16_wmma_qwen4_hcsd`] applies to a
    /// `[m × k]` BF16 weight at `batch_size` rows (H4 shared-down fold,
    /// `HIPFIRE_QWEN4_HC_FUSE >= 3`): exact gfx1151 on the Qwen4 F16 WMMA
    /// route, `m % 8 == 0`.
    pub fn gemm_bf16_xf32_f16_wmma_qwen4_hcsd_applies(
        &self,
        weight: &GpuTensor,
        m: usize,
        k: usize,
        batch_size: usize,
    ) -> bool {
        self.arch_caps.is_gfx1151()
            && m % 8 == 0
            && self.qwen4_f16_wmma_applies(weight, k, batch_size)
    }

    /// The shared-expert down projection, its BF16 scaled add into `routed` and
    /// the paired HC write in one GEMM: [`Gpu::gemm_bf16_xf32_f16_wmma_qwen4`]
    /// of `x` (F32, `[batch_size, k]`) followed by
    /// `bf16_scaled_add_batched(routed, ·, selector)` and
    /// `hyper_write(hc_streams, mixed = routed, hc_gates)`, bitwise.  `routed`
    /// (`[batch_size, m]`) is rewritten with the scaled-add result only when
    /// `hc_write_routed`; `hc_streams` is `[batch_size, 4 * m]` (BF16 bits when
    /// `hc_bf16`), `hc_gates` `[batch_size, 4]` from the paired HC read.
    /// Gate with [`Gpu::gemm_bf16_xf32_f16_wmma_qwen4_hcsd_applies`].
    #[allow(clippy::too_many_arguments)]
    pub fn gemm_bf16_xf32_f16_wmma_qwen4_hcsd(
        &mut self,
        weight: &GpuTensor,
        x: &GpuTensor,
        m: usize,
        k: usize,
        batch_size: usize,
        routed: &GpuTensor,
        selector: &GpuTensor,
        hc_streams: &GpuTensor,
        hc_gates: &GpuTensor,
        hc_bf16: bool,
        hc_write_routed: bool,
    ) -> HipResult<()> {
        if !self.gemm_bf16_xf32_f16_wmma_qwen4_hcsd_applies(weight, m, k, batch_size) {
            return Err(hip_bridge::HipError::new(
                1,
                "gemm_bf16_xf32_f16_wmma_qwen4_hcsd: route does not apply",
            ));
        }
        self.bind_thread()?;
        let w16 = self.ensure_bf16_f16_shadow(weight, m, k)?;
        let x16 = self.f16_x_or_convert(x, batch_size * k)?;
        const ENTRY: &str = "gemm_wmma_lds_128_256_32_64_k64_hcsd";
        let (module, source) = self.lds256_tile_module(ENTRY);
        self.ensure_kernel(module, source, ENTRY)?;
        let mut ap = w16;
        let mut xp = x16;
        let mut yp: *mut c_void = std::ptr::null_mut();
        let mut mi = m as i32;
        let mut ki = k as i32;
        let mut bi = batch_size as i32;
        let mut rp = routed.buf.as_ptr();
        let mut sp = selector.buf.as_ptr();
        let mut streams_ptr = hc_streams.buf.as_ptr();
        let mut gates_ptr = hc_gates.buf.as_ptr();
        let mut bf16_val = hc_bf16 as i32;
        let mut routed_val = hc_write_routed as i32;
        let mut lai = k as i32;
        let mut lxi = k as i32;
        let mut params: Vec<*mut c_void> = vec![
            &mut ap as *mut _ as *mut c_void,
            &mut xp as *mut _ as *mut c_void,
            &mut yp as *mut _ as *mut c_void,
            &mut mi as *mut _ as *mut c_void,
            &mut ki as *mut _ as *mut c_void,
            &mut bi as *mut _ as *mut c_void,
            &mut rp as *mut _ as *mut c_void,
            &mut sp as *mut _ as *mut c_void,
            &mut streams_ptr as *mut _ as *mut c_void,
            &mut gates_ptr as *mut _ as *mut c_void,
            &mut bf16_val as *mut _ as *mut c_void,
            &mut routed_val as *mut _ as *mut c_void,
            &mut lai as *mut _ as *mut c_void,
            &mut lxi as *mut _ as *mut c_void,
        ];
        // 128 x 256 block tile, 32 x 64 wave tiles: (128/32) * (256/64) waves.
        let grid = [m.div_ceil(128) as u32, batch_size.div_ceil(256) as u32, 1];
        self.launch_maybe_blob(ENTRY, grid, [512, 1, 1], 0, &mut params, || {
            let mut b = hip_bridge::KernargBlob::new();
            b.push_ptr(ap);
            b.push_ptr(xp);
            b.push_ptr(yp);
            b.push_i32(mi);
            b.push_i32(ki);
            b.push_i32(bi);
            b.push_ptr(rp);
            b.push_ptr(sp);
            b.push_ptr(streams_ptr);
            b.push_ptr(gates_ptr);
            b.push_i32(bf16_val);
            b.push_i32(routed_val);
            b.push_i32(lai);
            b.push_i32(lxi);
            b
        })
    }

    /// The shared-down projection for the HC row fold (`HIPFIRE_QWEN4_HC_ROW_FOLD`):
    /// [`Gpu::gemm_bf16_xf32_f16_wmma_qwen4_hcsd`]'s GEMM and BF16 rounding of
    /// `acc + 0.0f`, stored as BF16 bits to `out` (`[batch_size, m]`, at least
    /// `batch_size * m * 2` bytes; the fold and HC write are then
    /// [`Gpu::hc_row_fold_norm_gate`]'s).  Gate with
    /// [`Gpu::gemm_bf16_xf32_f16_wmma_qwen4_hcsd_applies`].
    /// idea from Gufo upstream (gufo-org/gufo @1071b361, MIT)
    #[allow(clippy::too_many_arguments)]
    pub fn gemm_bf16_xf32_f16_wmma_qwen4_bf16st(
        &mut self,
        weight: &GpuTensor,
        x: &GpuTensor,
        m: usize,
        k: usize,
        batch_size: usize,
        out: &GpuTensor,
    ) -> HipResult<()> {
        if !self.gemm_bf16_xf32_f16_wmma_qwen4_hcsd_applies(weight, m, k, batch_size)
            || out.buf.size() < batch_size * m * 2
        {
            return Err(hip_bridge::HipError::new(
                1,
                "gemm_bf16_xf32_f16_wmma_qwen4_bf16st: route does not apply",
            ));
        }
        self.bind_thread()?;
        let w16 = self.ensure_bf16_f16_shadow(weight, m, k)?;
        let x16 = self.f16_x_or_convert(x, batch_size * k)?;
        const ENTRY: &str = "gemm_wmma_lds_128_256_32_64_k64_bf16st";
        let (module, source) = self.lds256_tile_module(ENTRY);
        self.ensure_kernel(module, source, ENTRY)?;
        let mut ap = w16;
        let mut xp = x16;
        let mut yp = out.buf.as_ptr();
        let mut mi = m as i32;
        let mut ki = k as i32;
        let mut bi = batch_size as i32;
        let mut lai = k as i32;
        let mut lxi = k as i32;
        let mut params: Vec<*mut c_void> = vec![
            &mut ap as *mut _ as *mut c_void,
            &mut xp as *mut _ as *mut c_void,
            &mut yp as *mut _ as *mut c_void,
            &mut mi as *mut _ as *mut c_void,
            &mut ki as *mut _ as *mut c_void,
            &mut bi as *mut _ as *mut c_void,
            &mut lai as *mut _ as *mut c_void,
            &mut lxi as *mut _ as *mut c_void,
        ];
        let grid = [m.div_ceil(128) as u32, batch_size.div_ceil(256) as u32, 1];
        self.launch_maybe_blob(ENTRY, grid, [512, 1, 1], 0, &mut params, || {
            let mut b = hip_bridge::KernargBlob::new();
            b.push_ptr(ap);
            b.push_ptr(xp);
            b.push_ptr(yp);
            b.push_i32(mi);
            b.push_i32(ki);
            b.push_i32(bi);
            b.push_i32(lai);
            b.push_i32(lxi);
            b
        })
    }

    /// `Y[b, m] = Σ_k A[m, k]·X[b, k]` (A `[M, K]`, X `[B, K]` F16, Y `[B, M]`
    /// F32) on one tile of `GEMM_F16_X_F16_WMMA_LDS_SPLITK_SRC`.  With
    /// `tile.split > 1` the K-split partials go to the shared deterministic
    /// K-split scratch (`split·B·M` F32) and are added in ascending split
    /// order.  gfx1201 and gfx1151 only; `K % (ks·split) == 0`.
    #[allow(clippy::too_many_arguments)]
    pub fn gemm_f16_x_f16_wmma_lds_splitk(
        &mut self,
        a_f16: &GpuTensor,
        x_f16: &GpuTensor,
        y_f32: &GpuTensor,
        m: usize,
        k: usize,
        batch_size: usize,
        tile: LdsTileSplitK,
    ) -> HipResult<()> {
        if m == 0 || batch_size == 0 {
            return Ok(());
        }
        assert!(
            self.arch_caps.is_gfx1201() || self.arch_caps.is_gfx1151(),
            "gemm_f16_x_f16_wmma_lds_splitk is gfx1201/gfx1151-only (arch {})",
            self.arch
        );
        assert!(
            k > 0 && k % (tile.ks * tile.split) == 0,
            "gemm_f16_x_f16_wmma_lds_splitk: K must be a positive multiple of {} (got {k})",
            tile.ks * tile.split
        );
        assert!(
            a_f16.numel() >= m * k
                && x_f16.numel() >= batch_size * k
                && y_f32.numel() >= batch_size * m,
            "gemm_f16_x_f16_wmma_lds_splitk: operands too small for [{m} x {k}] x {batch_size}"
        );
        self.bind_thread()?;
        const MODULE: &str = "gemm_wmma_lds_splitk";
        let entry = tile.entry();
        self.ensure_kernel(MODULE, kernels::GEMM_F16_X_F16_WMMA_LDS_SPLITK_SRC, &entry)?;
        let ap = a_f16.buf.as_ptr();
        let xp = x_f16.buf.as_ptr();
        let yp = if tile.split > 1 {
            let partial_bytes = tile.partials_bytes(batch_size, m).ok_or_else(|| {
                hip_bridge::HipError::new(
                    0,
                    "gemm_f16_x_f16_wmma_lds_splitk: K-split partials extent overflow",
                )
            })?;
            self.ensure_ksplit_det_partials(partial_bytes)?
        } else {
            y_f32.buf.as_ptr()
        };
        let mi = m as i32;
        let ki = k as i32;
        let bi = batch_size as i32;
        let mut params: Vec<*mut c_void> = vec![
            &ap as *const _ as *mut c_void,
            &xp as *const _ as *mut c_void,
            &yp as *const _ as *mut c_void,
            &mi as *const _ as *mut c_void,
            &ki as *const _ as *mut c_void,
            &bi as *const _ as *mut c_void,
        ];
        let threads = ((tile.bm / tile.wm) * (tile.bn / tile.wn) * 32) as u32;
        let grid = [
            m.div_ceil(tile.bm) as u32,
            batch_size.div_ceil(tile.bn) as u32,
            tile.split as u32,
        ];
        self.launch_maybe_blob(&entry, grid, [threads, 1, 1], 0, &mut params, || {
            let mut b = hip_bridge::KernargBlob::new();
            b.push_ptr(ap);
            b.push_ptr(xp);
            b.push_ptr(yp);
            b.push_i32(mi);
            b.push_i32(ki);
            b.push_i32(bi);
            b
        })?;
        if tile.split == 1 {
            return Ok(());
        }
        const REDUCE: &str = "qwen4_wmma_lds_reduce";
        self.ensure_kernel(MODULE, kernels::GEMM_F16_X_F16_WMMA_LDS_SPLITK_SRC, REDUCE)?;
        let pp = yp;
        let op = y_f32.buf.as_ptr();
        let ni = (batch_size * m) as i32;
        let si = tile.split as i32;
        let mut params: Vec<*mut c_void> = vec![
            &pp as *const _ as *mut c_void,
            &op as *const _ as *mut c_void,
            &ni as *const _ as *mut c_void,
            &si as *const _ as *mut c_void,
        ];
        self.launch_maybe_blob(
            REDUCE,
            [(batch_size * m).div_ceil(256) as u32, 1, 1],
            [256, 1, 1],
            0,
            &mut params,
            || {
                let mut b = hip_bridge::KernargBlob::new();
                b.push_ptr(pp);
                b.push_ptr(op);
                b.push_i32(ni);
                b.push_i32(si);
                b
            },
        )
    }

    /// Pitched F16 weights/activations to packed `[B, M]` F32 output on gfx1201.
    /// Only the four supported unsplit k64 tiles are admitted: accumulation is
    /// ascending K in one accumulator, with no split scratch or reduction.
    /// `lda` and `ldx` are element pitches, at least K and divisible by 16.
    #[allow(clippy::too_many_arguments)]
    pub fn gemm_f16_x_f16_wmma_lds_splitk_ld(
        &mut self,
        a_f16: &GpuTensor,
        x_f16: &GpuTensor,
        y_f32: &GpuTensor,
        m: usize,
        k: usize,
        batch_size: usize,
        tile: LdsTileSplitK,
        lda: usize,
        ldx: usize,
    ) -> HipResult<()> {
        if m == 0 || batch_size == 0 {
            return Ok(());
        }
        assert!(
            self.arch_caps.is_gfx1201(),
            "gemm_f16_x_f16_wmma_lds_splitk_ld is gfx1201-only (arch {})",
            self.arch
        );
        assert_eq!(a_f16.dtype, DType::F16, "splitk_ld: A must be F16");
        assert_eq!(x_f16.dtype, DType::F16, "splitk_ld: X must be F16");
        assert_eq!(y_f32.dtype, DType::F32, "splitk_ld: Y must be F32");
        assert!(
            splitk_ld_supported(tile, k, lda, ldx),
            "gemm_f16_x_f16_wmma_lds_splitk_ld: unsupported tile/K/pitch: {tile:?}, K={k}, lda={lda}, ldx={ldx}"
        );
        Self::check_lds_pitch(
            "gemm_f16_x_f16_wmma_lds_splitk_ld",
            a_f16,
            x_f16,
            m,
            k,
            batch_size,
            lda,
            ldx,
        );
        assert!(
            y_f32.numel() >= batch_size * m,
            "gemm_f16_x_f16_wmma_lds_splitk_ld: output too small for [{batch_size}, {m}]"
        );
        self.bind_thread()?;
        let entry = splitk_ld_entry(tile).expect("validated pitched split1 tile");
        self.ensure_kernel(
            "gemm_wmma_lds_splitk",
            kernels::GEMM_F16_X_F16_WMMA_LDS_SPLITK_SRC,
            entry,
        )?;
        let ap = a_f16.buf.as_ptr();
        let xp = x_f16.buf.as_ptr();
        let yp = y_f32.buf.as_ptr();
        let mi = m as i32;
        let ki = k as i32;
        let bi = batch_size as i32;
        let lai = lda as i32;
        let lxi = ldx as i32;
        let mut params: [*mut c_void; 8] = [
            &ap as *const _ as *mut c_void,
            &xp as *const _ as *mut c_void,
            &yp as *const _ as *mut c_void,
            &mi as *const _ as *mut c_void,
            &ki as *const _ as *mut c_void,
            &bi as *const _ as *mut c_void,
            &lai as *const _ as *mut c_void,
            &lxi as *const _ as *mut c_void,
        ];
        let threads = ((tile.bm / tile.wm) * (tile.bn / tile.wn) * 32) as u32;
        let grid = [
            m.div_ceil(tile.bm) as u32,
            batch_size.div_ceil(tile.bn) as u32,
            1,
        ];
        self.launch_maybe_blob(entry, grid, [threads, 1, 1], 0, &mut params, || {
            let mut b = hip_bridge::KernargBlob::new();
            b.push_ptr(ap);
            b.push_ptr(xp);
            b.push_ptr(yp);
            b.push_i32(mi);
            b.push_i32(ki);
            b.push_i32(bi);
            b.push_i32(lai);
            b.push_i32(lxi);
            b
        })
    }

    /// gfx1201 tile for the Qwen4 BF16 projections, measured on the R9700
    /// against a 25-tile sweep (event-timed, 10-20 reps;
    /// `qcal/release-0.4.0/qwen4-hc-wmma/logs/sweep{1,2}.txt`), multirow in
    /// brackets:
    ///
    /// * M < 512 (HC input_mix_down 320, the M = 4 hyper-write gate, M = 1):
    ///   64 x 128 / 32 x 64 pipelined, 4-way K split when K % 256 == 0.
    ///   320 x 20480 x 1536 0.340 ms (4.78), 320 x 20480 x 512 0.129 (1.57),
    ///   320 x 10240 x 1900 0.217 (1.15), 320 x 10240 x 1131 0.133 (0.71).
    ///   The split also shortens each F32 accumulation chain: max error
    ///   against an F64 reference falls from 2.3e-5 to 3.7e-6 of max |y| at
    ///   K = 20480.
    /// * 512 <= M < 1024: 128 x 128 / 32 x 64, 512 x 2560 x 1900 0.082 (0.52).
    /// * M >= 1024: 128 x 256 / 32 x 64, 20480 x 2560 x 1536 2.09 ms (64.1),
    ///   5120 x 2560 x 1536 0.49 (7.88), 2560 x 2560 x 1900 0.33 (2.48).
    pub fn qwen4_lds_tile_gfx1201(m: usize, k: usize) -> LdsTileSplitK {
        match m {
            0..512 if k % 256 == 0 => LdsTileSplitK::new(64, 128, 32, 64, true, 4),
            0..512 => LdsTileSplitK::new(64, 128, 32, 64, true, 1),
            512..1024 => LdsTileSplitK::new(128, 128, 32, 64, false, 1),
            _ => LdsTileSplitK::new(128, 256, 32, 64, false, 1),
        }
    }

    /// Bytes of the shared deterministic K-split partials scratch that
    /// [`Self::gemm_f16_x_f16_wmma_lds_splitk`] sizes for the
    /// [`Self::qwen4_lds_tile_gfx1201`] tile of a `[m x k]` GEMM over `rows`
    /// token rows: `split * rows * m * 4`, or 0 when the GEMM is empty, the tile
    /// does not split, or `k` is not a positive multiple of `ks * split` (the
    /// launcher would reject it, so the split route is unreachable and uses its
    /// fallback with no partials). `None` only on `usize` overflow.
    pub fn qwen4_prefill_ksplit_bytes(rows: usize, m: usize, k: usize) -> Option<usize> {
        if m == 0 || rows == 0 {
            return Some(0);
        }
        let tile = Self::qwen4_lds_tile_gfx1201(m, k);
        if k == 0 || k % (tile.ks * tile.split) != 0 {
            return Some(0);
        }
        if tile.split > 1 {
            tile.partials_bytes(rows, m)
        } else {
            Some(0)
        }
    }

    /// Exact BF16-weight × F32-input multirow GEMM with four- and
    /// sixteen-token tile variants. The four-row reference and the gfx1151
    /// variant reuse widened weights across their token rows while retaining
    /// the reference accumulation and reduction association.
    #[allow(clippy::too_many_arguments)]
    pub fn gemm_bf16_xf32_multirow(
        &mut self,
        weight: &GpuTensor,
        x: &GpuTensor,
        y: &GpuTensor,
        m: usize,
        k: usize,
        batch_size: usize,
    ) -> HipResult<()> {
        self.bind_thread()?;
        if weight.dtype != DType::BF16 || x.dtype != DType::F32 || y.dtype != DType::F32 {
            return Err(hip_bridge::HipError::new(
                0,
                "gemm_bf16_xf32_multirow requires BF16 weights and F32 activations/output",
            ));
        }
        if m == 0 || k == 0 || batch_size == 0 || batch_size <= 1 {
            return Err(hip_bridge::HipError::new(
                0,
                &format!(
                    "gemm_bf16_xf32_multirow requires M,K>0 and batch_size>1 (got M={m} K={k} N={batch_size})"
                ),
            ));
        }
        let weight_bytes = m
            .checked_mul(k)
            .and_then(|elements| elements.checked_mul(2))
            .ok_or_else(|| hip_bridge::HipError::new(0, "BF16 multirow weight size overflows"))?;
        let x_bytes = batch_size
            .checked_mul(k)
            .and_then(|elements| elements.checked_mul(4))
            .ok_or_else(|| hip_bridge::HipError::new(0, "BF16 multirow input size overflows"))?;
        let y_bytes = batch_size
            .checked_mul(m)
            .and_then(|elements| elements.checked_mul(4))
            .ok_or_else(|| hip_bridge::HipError::new(0, "BF16 multirow output size overflows"))?;
        if weight.buf.size() < weight_bytes || x.buf.size() < x_bytes || y.buf.size() < y_bytes {
            return Err(hip_bridge::HipError::new(
                0,
                "gemm_bf16_xf32_multirow buffer capacity is too small",
            ));
        }
        // gfx1151 tile selection, measured on the production prefill shapes
        // (`.codeinsight+research/qwen4/pp500-kernel-check/dense-multirow-pick`
        // for the original sixteen-token tile, `dense-loadvec` for the
        // sixteen-row tile below: every arm bitwise-equal to the four-row
        // kernel on the twenty-shape list, 10 warmups + 5 alternating event
        // pairs per arm against it).
        //
        // The gfx1151 tile owns sixteen output rows and two token rows per
        // wave, which is four times less activation traffic per FMA than the
        // four-row tile.  Its token tile is the fast-varying grid dimension so
        // a row group's sixteen weight rows stay resident across the tile
        // sweep; without that ordering the weight stream leaves DRAM once per
        // tile and the shape is several times slower.  Measured against the
        // previous sixteen-token tile (2.30x geomean over the six required
        // shapes, 2.02x over all twenty):
        //
        //   (10240,2560, 291)  7.26 ms -> 2.96 ms | (12288,2560, 291) 8.51 -> 3.43
        //   (2560, 6144, 291)  3.67 ms -> 1.71 ms | (320, 10240, 291) 0.62 -> 0.36
        //   (10240,2560, 512) 12.02 ms -> 5.00 ms | (248320,2560, 291) 166.8 -> 75.3
        //
        // The allowlist is unchanged; only the tile shape and grid inside this
        // route change.  blockIdx.y is sixteen bits, so a wave may only cover
        // a token tile while the row groups (r16w4t) and token tiles (r16w4)
        // fit that limit.  No other bound on the token count: past 2048
        // tokens the four-row kernel is 2.0-2.6x slower per row on gfx1201
        // while r16w4 keeps its rate through 8192 (2560 x 2560 at 4096:
        // 11.40 vs 5.52 ms; 320 x 10240 at 8192: 13.22 vs 5.27 ms).
        let r16_shape = self.arch_caps.has_gfx11_plus_simt()
            && batch_size >= 64
            && batch_size.div_ceil(8) <= 0xffff
            && m.div_ceil(16) <= 0xffff
            && matches!(
                (m, k),
                (10240, 2560)
                    | (12288, 2560)
                    | (2560, 6144)
                    | (6144, 2560)
                    | (320, 10240)
                    | (248320, 2560)
                    // Qwen4 shared-expert gate/up and router (N = 512 prefill).
                    | (640, 2560)
                    | (512, 2560)
                    // Qwen4 PLE value projection (2.68 vs 4.96 ms at N = 1131).
                    | (2560, 2560)
            );
        // K % 256 == 0 (every allowlisted shape): four waves share each
        // weight chunk through LDS; bitwise identical to the R16 kernel.
        // Row groups sweep fastest unless the weight outweighs the activations.
        let tokens_fast = m * 2 > batch_size * 4;
        let (kernel, source, grid, block) = if r16_shape && k % 256 == 0 && tokens_fast {
            (
                "gemm_bf16_xf32_multirow_r16w4t_gfx1151",
                kernels::GEMM_BF16_XF32_MULTIROW_R16_GFX1151_SRC,
                [batch_size.div_ceil(8) as u32, m.div_ceil(16) as u32, 1],
                128,
            )
        } else if r16_shape && k % 256 == 0 {
            (
                "gemm_bf16_xf32_multirow_r16w4_gfx1151",
                kernels::GEMM_BF16_XF32_MULTIROW_R16_GFX1151_SRC,
                [m.div_ceil(16) as u32, batch_size.div_ceil(8) as u32, 1],
                128,
            )
        } else if r16_shape {
            (
                "gemm_bf16_xf32_multirow_r16_gfx1151",
                kernels::GEMM_BF16_XF32_MULTIROW_R16_GFX1151_SRC,
                [batch_size.div_ceil(2) as u32, m.div_ceil(16) as u32, 1],
                32,
            )
        } else if self.arch_caps.has_gfx11_plus_simt()
            && k.is_multiple_of(8)
            && (257..=512).contains(&k)
        {
            // One thread per output row, weights in LDS, 64 tokens per
            // block; bitwise identical to the four-row kernel.
            (
                "gemm_bf16_xf32_multirow_pto2",
                kernels::GEMM_BF16_XF32_MULTIROW_SRC,
                [m.div_ceil(32) as u32, batch_size.div_ceil(64) as u32, 1],
                256,
            )
        } else if self.arch_caps.has_gfx11_plus_simt()
            && k.is_multiple_of(8)
            && (513..=768).contains(&k)
        {
            // Small K: one wave keeps its four tokens' X in registers and
            // walks sixteen rows; bitwise identical to the four-row kernel.
            (
                "gemm_bf16_xf32_multirow_rows3",
                kernels::GEMM_BF16_XF32_MULTIROW_SRC,
                [m.div_ceil(16) as u32, batch_size.div_ceil(4) as u32, 1],
                32,
            )
        } else {
            (
                "gemm_bf16_xf32_multirow",
                kernels::GEMM_BF16_XF32_MULTIROW_SRC,
                [m as u32, batch_size.div_ceil(4) as u32, 1],
                32,
            )
        };
        let shared_bytes = if kernel == "gemm_bf16_xf32_multirow_pto2" {
            (32 * (k / 2 + 1) * 4) as u32
        } else {
            0
        };
        self.ensure_kernel(kernel, source, kernel)?;
        let wp = weight.buf.as_ptr();
        let xp = x.buf.as_ptr();
        let yp = y.buf.as_ptr();
        let mv = m as i32;
        let kv = k as i32;
        let nv = batch_size as i32;
        let mut params = [
            &wp as *const _ as *mut c_void,
            &xp as *const _ as *mut c_void,
            &yp as *const _ as *mut c_void,
            &mv as *const _ as *mut c_void,
            &kv as *const _ as *mut c_void,
            &nv as *const _ as *mut c_void,
        ];
        let bytes = weight_bytes.saturating_add(x_bytes).saturating_add(y_bytes);
        let timer = crate::profile::begin_timer(&self.hip, "gemm", kernel, bytes);
        let result = self.launch_maybe_blob(
            kernel,
            grid,
            [block, 1, 1],
            shared_bytes,
            &mut params,
            || {
                let mut b = hip_bridge::KernargBlob::new();
                b.push_ptr(wp);
                b.push_ptr(xp);
                b.push_ptr(yp);
                b.push_i32(mv);
                b.push_i32(kv);
                b.push_i32(nv);
                b
            },
        );
        if let Some(t) = timer {
            t.finish(&self.hip);
        }
        result
    }

    /// The incumbent gfx1151 sixteen-row `gemm_bf16_xf32_multirow_r16w4_gfx1151` tile launched
    /// unconditionally (grid `[ceil(m/16), ceil(n/8), 1]`, block 128), bypassing
    /// [`Gpu::gemm_bf16_xf32_multirow`]'s allowlist: the same kernel and launch it selects for
    /// an allowlisted `tokens_fast == false` shape (2560 x 2560 at `n = 4096`), for baselines at
    /// other shapes. Admission mirrors the r16 route: exact gfx1151, BF16 weight, F32 X / Y,
    /// `m % 16 == 0`, `k % 256 == 0`, `n >= 64`, 16-bit grid dimensions.
    #[allow(clippy::too_many_arguments)]
    pub fn gemm_bf16_xf32_multirow_r16w4_forced(
        &mut self,
        weight: &GpuTensor,
        x: &GpuTensor,
        y: &GpuTensor,
        m: usize,
        k: usize,
        n: usize,
    ) -> HipResult<()> {
        self.bind_thread()?;
        let err =
            |msg: String| hip_bridge::HipError::new(0, &format!("multirow_r16w4_forced: {msg}"));
        if self.arch != "gfx1151" {
            return Err(err(format!(
                "requires exact gfx1151 (device is {})",
                self.arch
            )));
        }
        if weight.dtype != DType::BF16 || x.dtype != DType::F32 || y.dtype != DType::F32 {
            return Err(err(
                "requires BF16 weights and F32 activations/output".into()
            ));
        }
        if m == 0
            || m % 16 != 0
            || k == 0
            || k % 256 != 0
            || n < 64
            || n.div_ceil(8) > 0xffff
            || m.div_ceil(16) > 0xffff
        {
            return Err(err(format!(
                "shape M={m} K={k} N={n} outside r16w4 (M%16==0, K%256==0, N>=64)"
            )));
        }
        let (wb, xb, yb) = (m * k * 2, n * k * 4, n * m * 4);
        if weight.buf.size() < wb || x.buf.size() < xb || y.buf.size() < yb {
            return Err(err("buffer capacity is too small".into()));
        }
        let kernel = "gemm_bf16_xf32_multirow_r16w4_gfx1151";
        self.ensure_kernel(
            kernel,
            kernels::GEMM_BF16_XF32_MULTIROW_R16_GFX1151_SRC,
            kernel,
        )?;
        let (wp, xp, yp) = (weight.buf.as_ptr(), x.buf.as_ptr(), y.buf.as_ptr());
        let (mv, kv, nv) = (m as i32, k as i32, n as i32);
        let mut params = [
            &wp as *const _ as *mut c_void,
            &xp as *const _ as *mut c_void,
            &yp as *const _ as *mut c_void,
            &mv as *const _ as *mut c_void,
            &kv as *const _ as *mut c_void,
            &nv as *const _ as *mut c_void,
        ];
        let timer = crate::profile::begin_timer(&self.hip, "gemm", kernel, wb + xb + yb);
        let result = self.launch_maybe_blob(
            kernel,
            [m.div_ceil(16) as u32, n.div_ceil(8) as u32, 1],
            [128, 1, 1],
            0,
            &mut params,
            || {
                let mut b = hip_bridge::KernargBlob::new();
                b.push_ptr(wp);
                b.push_ptr(xp);
                b.push_ptr(yp);
                b.push_i32(mv);
                b.push_i32(kv);
                b.push_i32(nv);
                b
            },
        );
        if let Some(t) = timer {
            t.finish(&self.hip);
        }
        result
    }
    /// Qwen4 qt=53 dense batched projection against G128-rotated rows.
    ///
    /// gfx1151 uses a four-row kernel that shares each decoded weight group
    /// across prompt rows but keeps the scalar gemv accumulator/reduction
    /// association.  Other architectures retain the original one-row
    /// batched kernel.
    #[allow(clippy::too_many_arguments)]
    pub fn gemm_mq4g128v2_batched(
        &mut self,
        a_raw: &GpuTensor,
        x: &GpuTensor,
        y: &GpuTensor,
        m: usize,
        k: usize,
        batch_size: usize,
    ) -> HipResult<()> {
        if self.route_rows(batch_size) == 1 {
            return self.gemv_mq4g128v2(a_raw, x, y, m, k);
        }

        self.bind_thread()?;
        let gfx1151_multirow =
            self.route_rows(batch_size) > 1 && self.arch_caps.has_gfx11_plus_simt();
        let (func, source, token_tiles) = if gfx1151_multirow {
            (
                "gemm_mq4g128v2_multirow_gfx1151",
                kernels::GEMM_MQ4G128V2_MULTIROW_GFX1151_SRC,
                batch_size.div_ceil(4),
            )
        } else {
            (
                "gemm_mq4g128v2_batched",
                kernels::GEMM_MQ4G128V2_BATCHED_SRC,
                batch_size,
            )
        };
        self.ensure_kernel(func, source, func)?;
        let a_ptr = a_raw.buf.as_ptr();
        let x_ptr = x.buf.as_ptr();
        let y_ptr = y.buf.as_ptr();
        let m_val = m as i32;
        let k_val = k as i32;
        let n_val = batch_size as i32;
        let mut params = [
            &a_ptr as *const _ as *mut c_void,
            &x_ptr as *const _ as *mut c_void,
            &y_ptr as *const _ as *mut c_void,
            &m_val as *const _ as *mut c_void,
            &k_val as *const _ as *mut c_void,
            &n_val as *const _ as *mut c_void,
        ];
        let weight_bytes = m
            .saturating_mul(k.div_ceil(128).saturating_mul(68))
            .saturating_mul(token_tiles);
        let bytes = weight_bytes
            .saturating_add(batch_size.saturating_mul(k.saturating_add(m).saturating_mul(4)));
        let timer = crate::profile::begin_timer(&self.hip, "gemm", func, bytes);
        let result = self.launch_maybe_blob(
            func,
            [m as u32, token_tiles as u32, 1],
            [32, 1, 1],
            0,
            &mut params,
            || {
                let mut b = hip_bridge::KernargBlob::new();
                b.push_ptr(a_ptr);
                b.push_ptr(x_ptr);
                b.push_ptr(y_ptr);
                b.push_i32(m_val);
                b.push_i32(k_val);
                b.push_i32(n_val);
                b
            },
        );
        if let Some(t) = timer {
            t.finish(&self.hip);
        }
        result
    }

    /// HFP4G32 / MFP4G32 grouped-WMMA-GEMM for MoE prefill — sister of
    /// `gemm_hfq4g256_moe_grouped_wmma_k2` but on the FP4G32 dequant. Same
    /// kernarg layout, same expert_tile_ids / sorted_slot_index contract.
    /// Tile (blockIdx.x, blockIdx.y) gathers row `sorted_slot_index[slot_start
    /// + m_lane]` (with -1 meaning "padding lane — zero B") and applies the
    /// weights of expert `expert_tile_ids[blockIdx.y]`. Sentinel `< 0` early-
    /// returns the tile so the dispatcher can launch up to m_total_max/16
    /// tiles without an m_total dtoh sync.
    ///
    /// `x_row_div` selects the X gather layout (same as HFQ4 sister):
    ///   gate_up: x_src = x_rot_batch [N × K], x_row_div = K_TOP
    ///   down:    x_src = rot_batch [N*K_TOP × K], x_row_div = 1
    /// `x_src_rows` is the number of rows in x_src (N or N*K_TOP).
    ///
    /// **gfx12 only.** gfx11 and older archs are not implemented and will
    /// panic — call sites should arch-gate before dispatching here.
    #[allow(clippy::too_many_arguments)]
    pub fn gemm_hfp4g32_moe_grouped_wmma(
        &mut self,
        expert_weight_ptrs: &GpuTensor, // [E] u64
        expert_tile_ids: &GpuTensor,    // [m_total / 16] i32
        sorted_slot_index: &GpuTensor,  // [m_total] i32
        x_src: &GpuTensor,              // [x_src_rows × K] f32 (auto-converted to FP16)
        y_grouped: &GpuTensor,          // [m_total × M] f32, written direct
        m: usize,
        k: usize,
        x_row_div: usize,
        m_total: usize,
        x_src_rows: usize,
    ) -> HipResult<()> {
        self.bind_thread()?;
        let n_experts_val = moe_expert_table_len(expert_weight_ptrs);
        if !self.arch_caps.is_rdna4() {
            panic!(
                "gemm_hfp4g32_moe_grouped_wmma: only gfx12 (RDNA4) is implemented; \
                 got arch={}. Add a wave32 sister kernel for non-gfx12 archs.",
                self.arch
            );
        }
        let kernel_name = "gemm_hfp4g32_moe_grouped_wmma_gfx12";
        let kernel_src = kernels::GEMM_HFP4G32_MOE_GROUPED_WMMA_GFX12_SRC;
        self.ensure_kernel(kernel_name, kernel_src, kernel_name)?;
        let x_f16_ptr = self.ensure_fp16_x(x_src, x_src_rows * k)?;

        let ep = expert_weight_ptrs.buf.as_ptr();
        let tp = expert_tile_ids.buf.as_ptr();
        let sp = sorted_slot_index.buf.as_ptr();
        let xp = x_f16_ptr;
        let yp = y_grouped.buf.as_ptr();
        let m_val = m as i32;
        let k_val = k as i32;
        let xrd_val = x_row_div as i32;
        let mt_val = m_total as i32;

        let mut params: Vec<*mut c_void> = vec![
            &ep as *const _ as *mut c_void,
            &tp as *const _ as *mut c_void,
            &sp as *const _ as *mut c_void,
            &xp as *const _ as *mut c_void,
            &yp as *const _ as *mut c_void,
            &m_val as *const _ as *mut c_void,
            &k_val as *const _ as *mut c_void,
            &xrd_val as *const _ as *mut c_void,
            &mt_val as *const _ as *mut c_void,
            &n_experts_val as *const _ as *mut c_void,
        ];

        let row_tiles = ((m + 15) / 16) as u32;
        let slot_tiles = ((m_total + 15) / 16) as u32;
        // BW estimate: gather X (fp16) + weight rows (HFP4G32: 18 B/group, K/32 groups
        // per row, ~m_total/E shared per tile) + write Y. Use the existing helper.
        let bytes = m_total * k * 2 + (m_total * m) * 4 + crate::profile::gemv_hfp4g32_bytes(m, k);
        let timer = crate::profile::begin_timer(&self.hip, "gemm", kernel_name, bytes);
        let result = self.launch_maybe_blob(
            kernel_name,
            [row_tiles, slot_tiles, 1],
            [32, 1, 1],
            0,
            &mut params,
            || {
                let mut b = hip_bridge::KernargBlob::new();
                b.push_ptr(ep);
                b.push_ptr(tp);
                b.push_ptr(sp);
                b.push_ptr(xp);
                b.push_ptr(yp);
                b.push_i32(m_val);
                b.push_i32(k_val);
                b.push_i32(xrd_val);
                b.push_i32(mt_val);
                b.push_i32(n_experts_val);
                b
            },
        );
        if let Some(t) = timer {
            t.finish(&self.hip);
        }
        result
    }

    pub fn gemm_hfq4g256_lmhead_wmma_gfx12(
        &mut self,
        a_raw: &GpuTensor,
        x: &GpuTensor,
        y: &GpuTensor,
        m: usize,
        k: usize,
        batch_size: usize,
    ) -> HipResult<()> {
        self.bind_thread()?;
        self.ensure_kernel(
            "gemm_hfq4g256_lmhead_wmma_gfx12",
            kernels::GEMM_HFQ4G256_LMHEAD_WMMA_GFX12_SRC,
            "gemm_hfq4g256_lmhead_wmma_gfx12",
        )?;
        let x_f16_ptr = self.ensure_fp16_x(x, batch_size * k)?;

        let mut a_ptr = a_raw.buf.as_ptr();
        let mut x_ptr = x_f16_ptr;
        let mut y_ptr = y.buf.as_ptr();
        let mut m_val = m as i32;
        let mut k_val = k as i32;
        let mut bs_val = batch_size as i32;

        let mut params: Vec<*mut c_void> = vec![
            &mut a_ptr as *mut _ as *mut c_void,
            &mut x_ptr as *mut _ as *mut c_void,
            &mut y_ptr as *mut _ as *mut c_void,
            &mut m_val as *mut _ as *mut c_void,
            &mut k_val as *mut _ as *mut c_void,
            &mut bs_val as *mut _ as *mut c_void,
        ];

        let row_tiles = (m + 15) / 16;
        let batch_tiles = (batch_size + 15) / 16;

        let bytes =
            crate::profile::gemv_hfq4g256_bytes(m, k) + batch_size * k * 2 + batch_size * m * 4;
        let timer = crate::profile::begin_timer(
            &self.hip,
            "gemm",
            "gemm_hfq4g256_lmhead_wmma_gfx12",
            bytes,
        );
        let result = self.launch_maybe_blob(
            "gemm_hfq4g256_lmhead_wmma_gfx12",
            [row_tiles as u32, batch_tiles as u32, 1],
            [32, 1, 1],
            0,
            &mut params,
            || {
                let mut b = hip_bridge::KernargBlob::new();
                b.push_ptr(a_ptr);
                b.push_ptr(x_ptr);
                b.push_ptr(y_ptr);
                b.push_i32(m_val);
                b.push_i32(k_val);
                b.push_i32(bs_val);
                b
            },
        );
        if let Some(t) = timer {
            t.finish(&self.hip);
        }
        result
    }
    pub fn gemm_q8_0_wmma_x64(
        &mut self,
        a: &GpuTensor,
        x: &GpuTensor,
        y: &GpuTensor,
        m: usize,
        k: usize,
        batch_size: usize,
    ) -> HipResult<()> {
        self.bind_thread()?;
        debug_assert_eq!(k % 32, 0, "gemm_q8_0_wmma_x64: K must be %32");
        debug_assert_eq!(batch_size % 64, 0, "gemm_q8_0_wmma_x64: N must be %64");
        self.ensure_kernel(
            "gemm_q8_0_wmma_x64",
            kernels::GEMM_Q8_0_WMMA_X64_SRC,
            "gemm_q8_0_wmma_x64",
        )?;
        let xp_owned = x.buf.as_ptr();
        let mut xp = if matches!(x.dtype, DType::F16) {
            xp_owned
        } else {
            self.ensure_fp16_x(x, batch_size * k)?
        };
        let mut a_p = a.buf.as_ptr();
        let mut y_p = y.buf.as_ptr();
        let mut m_val = m as i32;
        let mut k_val = k as i32;
        let mut n_val = batch_size as i32;
        let mut params: Vec<*mut c_void> = vec![
            &mut a_p as *mut _ as *mut c_void,
            &mut xp as *mut _ as *mut c_void,
            &mut y_p as *mut _ as *mut c_void,
            &mut m_val as *mut _ as *mut c_void,
            &mut k_val as *mut _ as *mut c_void,
            &mut n_val as *mut _ as *mut c_void,
        ];
        let row_tiles = (m + 15) / 16;
        let batch_tiles = (batch_size + 63) / 64;
        let bytes = m * (k / 32) * 34 + batch_size * k * 2 + batch_size * m * 4;
        let timer = crate::profile::begin_timer(&self.hip, "gemm", "gemm_q8_0_wmma_x64", bytes);
        let result = self.launch_maybe_blob(
            "gemm_q8_0_wmma_x64",
            [row_tiles as u32, batch_tiles as u32, 1],
            [32, 1, 1],
            0,
            &mut params,
            || {
                let mut b = hip_bridge::KernargBlob::new();
                b.push_ptr(a_p);
                b.push_ptr(xp);
                b.push_ptr(y_p);
                b.push_i32(m_val);
                b.push_i32(k_val);
                b.push_i32(n_val);
                b
            },
        );
        if let Some(t) = timer {
            t.finish(&self.hip);
        }
        result
    }
    /// Exact-gfx1030 sdot4 MMQ Q8_0 probe. This is intentionally not selected
    /// by any production dispatch path: it exists only for direct channel
    /// validation while beta's model and Redline behavior remain immutable.
    pub fn gemm_q8_0_mmq_gfx1030(
        &mut self,
        a: &GpuTensor,
        x: &GpuTensor,
        y: &GpuTensor,
        m: usize,
        k: usize,
        batch_size: usize,
    ) -> HipResult<()> {
        self.bind_thread()?;
        if !self.arch_caps.is_gfx1030() {
            return Err(hip_bridge::HipError::new(
                0,
                &format!(
                    "gemm_q8_0_mmq_gfx1030 requires exact gfx1030; current arch = {}",
                    self.arch
                ),
            ));
        }
        debug_assert_eq!(
            k % 128,
            0,
            "gemm_q8_0_mmq_gfx1030: K must be multiple of 128"
        );
        let kernel_name = "gemm_q8_0_mmq_gfx1030";
        self.ensure_kernel(kernel_name, kernels::GEMM_Q8_0_MMQ_GFX1030_SRC, kernel_name)?;
        let x_q8_ptr = self.ensure_q8_1_mmq_x(x, batch_size, k)?;
        let ap = a.buf.as_ptr();
        let xp = x_q8_ptr;
        let yp = y.buf.as_ptr();
        let m_val = m as i32;
        let k_val = k as i32;
        let n_val = batch_size as i32;
        let mut params: Vec<*mut c_void> = vec![
            &ap as *const _ as *mut c_void,
            &xp as *const _ as *mut c_void,
            &yp as *const _ as *mut c_void,
            &m_val as *const _ as *mut c_void,
            &k_val as *const _ as *mut c_void,
            &n_val as *const _ as *mut c_void,
        ];
        let row_tiles = ((m + 31) / 32) as u32;
        let col_tiles = ((batch_size + 127) / 128) as u32;
        let bytes = m * (k / 32) * 34 + batch_size * (k / 128) * 144 + batch_size * m * 4;
        let timer = crate::profile::begin_timer(&self.hip, "gemm", kernel_name, bytes);
        // Probe-only raw HIP launch: never enter the Redline recording seam.
        let result = launch_params_blob!(
            self,
            kernel_name,
            [row_tiles, col_tiles, 1],
            [256, 1, 1],
            0,
            params; ap, xp, yp, m_val, k_val, n_val
        );
        if let Some(t) = timer {
            t.finish(&self.hip);
        }
        result
    }

    /// Dense i8-WMMA MMQ GEMM for Q8_0 weights — 64x64 4-warp tile (gfx1151).
    /// Takes F32 `x` (auto-quantized to Q8_1), int8 WMMA at ~2x. Drop-in for
    /// `gemm_q8_0_wmma_4w`. Requires M%64==0, N%64==0, K%128==0.
    pub fn gemm_q8_0_mmq_4w_gfx1151(
        &mut self,
        a: &GpuTensor,
        x: &GpuTensor,
        y: &GpuTensor,
        m: usize,
        k: usize,
        batch_size: usize,
    ) -> HipResult<()> {
        self.bind_thread()?;
        if self.arch != "gfx1151" {
            return Err(hip_bridge::HipError::new(
                0,
                &format!(
                    "gemm_q8_0_mmq_4w_gfx1151 requires gfx1151; current arch = {}",
                    self.arch
                ),
            ));
        }
        let kernel_name = "gemm_q8_0_mmq_4w_gfx1151";
        self.ensure_kernel(
            kernel_name,
            kernels::GEMM_Q8_0_MMQ_4W_GFX1151_SRC,
            kernel_name,
        )?;
        let x_q8_ptr = self.ensure_q8_1_mmq_x(x, batch_size, k)?;

        let ap = a.buf.as_ptr();
        let xp = x_q8_ptr;
        let yp = y.buf.as_ptr();
        let m_val = m as i32;
        let k_val = k as i32;
        let n_val = batch_size as i32;
        let mut params: Vec<*mut c_void> = vec![
            &ap as *const _ as *mut c_void,
            &xp as *const _ as *mut c_void,
            &yp as *const _ as *mut c_void,
            &m_val as *const _ as *mut c_void,
            &k_val as *const _ as *mut c_void,
            &n_val as *const _ as *mut c_void,
        ];
        let row_tiles = ((m + 63) / 64) as u32;
        let col_tiles = ((batch_size + 63) / 64) as u32;
        let bytes = (m * k) + (batch_size * m) * 4;
        let timer = crate::profile::begin_timer(&self.hip, "gemm", kernel_name, bytes);
        let result = self.launch_maybe_blob(
            kernel_name,
            [row_tiles, col_tiles, 1],
            [128, 1, 1],
            0,
            &mut params,
            || {
                let mut b = hip_bridge::KernargBlob::new();
                b.push_ptr(ap);
                b.push_ptr(xp);
                b.push_ptr(yp);
                b.push_i32(m_val);
                b.push_i32(k_val);
                b.push_i32(n_val);
                b
            },
        );
        if let Some(t) = timer {
            t.finish(&self.hip);
        }
        result
    }

    pub fn gemm_q8_0_wmma_4w(
        &mut self,
        a: &GpuTensor,
        x: &GpuTensor,
        y: &GpuTensor,
        m: usize,
        k: usize,
        batch_size: usize,
    ) -> HipResult<()> {
        self.bind_thread()?;
        debug_assert_eq!(k % 32, 0, "gemm_q8_0_wmma_4w: K must be a multiple of 32");
        debug_assert_eq!(
            m % 64,
            0,
            "gemm_q8_0_wmma_4w: M must be a multiple of 64 (got {m})"
        );
        debug_assert_eq!(
            batch_size % 64,
            0,
            "gemm_q8_0_wmma_4w: N must be a multiple of 64 (got {batch_size})"
        );
        self.ensure_kernel(
            "gemm_q8_0_wmma_4w",
            kernels::GEMM_Q8_0_WMMA_4W_SRC,
            "gemm_q8_0_wmma_4w",
        )?;
        // Stage F32 → F16 input if needed. Uncached: callers reuse one
        // activation buffer with new contents per layer, which the
        // pointer-keyed `ensure_fp16_x` would hand back stale.
        let xp_owned = x.buf.as_ptr();
        let mut xp = if matches!(x.dtype, DType::F16) {
            xp_owned
        } else {
            self.convert_fp16_x_uncached(x, batch_size * k)?
        };

        let mut a_p = a.buf.as_ptr();
        let mut y_p = y.buf.as_ptr();
        let mut m_val = m as i32;
        let mut k_val = k as i32;
        let mut n_val = batch_size as i32;
        let mut params: Vec<*mut c_void> = vec![
            &mut a_p as *mut _ as *mut c_void,
            &mut xp as *mut _ as *mut c_void,
            &mut y_p as *mut _ as *mut c_void,
            &mut m_val as *mut _ as *mut c_void,
            &mut k_val as *mut _ as *mut c_void,
            &mut n_val as *mut _ as *mut c_void,
        ];
        let row_tiles = (m + 63) / 64;
        let batch_tiles = (batch_size + 63) / 64;
        let bytes = m * (k / 32) * 34 + batch_size * k * 2 + batch_size * m * 4;
        let timer = crate::profile::begin_timer(&self.hip, "gemm", "gemm_q8_0_wmma_4w", bytes);
        let result = launch_params_blob!(
            self,
            "gemm_q8_0_wmma_4w",
            [row_tiles as u32, batch_tiles as u32, 1],
            [128, 1, 1],
            0,
            params; a_p, xp, y_p, m_val, k_val, n_val
        );
        if let Some(t) = timer {
            t.finish(&self.hip);
        }
        result
    }
    /// F16 weight × F16 input → F32 batched GEMM, arch-routed.
    ///
    /// gfx11 takes the wave32 `gemm_f16_x_f16_wmma` kernel; gfx12 (RDNA4)
    /// takes the `gemm_f16_x_f16_wmma_gfx12` sister (half8 operands,
    /// `_w32_gfx12` builtin, contiguous-per-half C mapping) because the gfx11
    /// `_w32` builtin does not compile for gfx1201. Same operand contract,
    /// same grid/block, same `[B, M]` F32 result — purely an ISA-level swap.
    pub fn gemm_f16_x_f16_wmma(
        &mut self,
        a_f16: &GpuTensor,
        x_f16: &GpuTensor,
        y_f32: &GpuTensor,
        m: usize,
        k: usize,
        batch_size: usize,
    ) -> HipResult<()> {
        self.bind_thread()?;
        let (module, source, symbol) = if self.arch_caps.has_wmma_w32_gfx12() {
            (
                "gemm_f16_x_f16_wmma_gfx12",
                kernels::GEMM_F16_X_F16_WMMA_GFX12_SRC,
                "gemm_f16_x_f16_wmma_gfx12",
            )
        } else {
            (
                "gemm_f16_x_f16_wmma",
                kernels::GEMM_F16_X_F16_WMMA_SRC,
                "gemm_f16_x_f16_wmma",
            )
        };
        self.ensure_kernel(module, source, symbol)?;
        let ap = a_f16.buf.as_ptr();
        let mi = m as i32;
        let ki = k as i32;
        let grid_m = m.div_ceil(16) as u32;
        // 16-row batch tiles ride grid.y: launch row pieces of at most
        // GRID_YZ_MAX tiles with X/Y advanced to the piece's first row.
        for (start, n) in crate::gemv::grid_yz_chunks(batch_size.div_ceil(16)) {
            let row0 = start * 16;
            let rows = (n * 16).min(batch_size - row0);
            let xp = crate::gemv::ptr_add_bytes(x_f16.buf.as_ptr(), row0 * k * 2);
            let yp = crate::gemv::ptr_add_bytes(y_f32.buf.as_ptr(), row0 * m * 4);
            let bi = rows as i32;
            let mut params: Vec<*mut c_void> = vec![
                &ap as *const _ as *mut c_void,
                &xp as *const _ as *mut c_void,
                &yp as *const _ as *mut c_void,
                &mi as *const _ as *mut c_void,
                &ki as *const _ as *mut c_void,
                &bi as *const _ as *mut c_void,
            ];
            self.launch_maybe_blob(
                module,
                [grid_m, n as u32, 1],
                [32, 1, 1],
                0,
                &mut params,
                || {
                    let mut b = hip_bridge::KernargBlob::new();
                    b.push_ptr(ap);
                    b.push_ptr(xp);
                    b.push_ptr(yp);
                    b.push_i32(mi);
                    b.push_i32(ki);
                    b.push_i32(bi);
                    b
                },
            )?;
        }
        Ok(())
    }

    /// LDS-staged 128×128 macro-tile GEMM: `Y[b, m] = bias[m] + Σ_k A[m,k]·X[b,k]`.
    ///
    /// Same operand contract as [`Gpu::gemm_f16_x_f16_wmma`], with the bias
    /// fused into the epilogue so callers can drop the separate `bias_add_f32`
    /// pass. Pass `bias = None` to skip it.
    ///
    /// Requires `K % 64 == 0` (the K-stage depth). Callers with a ragged K must
    /// route to `gemm_f16_x_f16_wmma`.
    pub fn gemm_f16_x_f16_wmma_lds(
        &mut self,
        a_f16: &GpuTensor,
        x_f16: &GpuTensor,
        y_f32: &GpuTensor,
        bias_f32: Option<&GpuTensor>,
        m: usize,
        k: usize,
        batch_size: usize,
    ) -> HipResult<()> {
        self.bind_thread()?;
        assert!(
            k % 64 == 0,
            "gemm_f16_x_f16_wmma_lds: K must be a multiple of 64 (got {k})"
        );
        if let Some(b) = bias_f32 {
            assert_eq!(
                b.dtype,
                DType::F32,
                "gemm_f16_x_f16_wmma_lds: `bias_f32` must be F32"
            );
        }
        self.ensure_kernel(
            "gemm_f16_x_f16_wmma_lds",
            kernels::GEMM_F16_X_F16_WMMA_LDS_SRC,
            "gemm_f16_x_f16_wmma_lds",
        )?;
        let ap = a_f16.buf.as_ptr();
        let xp = x_f16.buf.as_ptr();
        let yp = y_f32.buf.as_ptr();
        let bp = bias_f32.map_or(std::ptr::null_mut(), |t| t.buf.as_ptr());
        let mut mi = m as i32;
        let mut ki = k as i32;
        let mut bi = batch_size as i32;
        let mut hb = i32::from(bias_f32.is_some());
        let mut params: Vec<*mut c_void> = vec![
            &ap as *const _ as *mut c_void,
            &xp as *const _ as *mut c_void,
            &yp as *const _ as *mut c_void,
            &bp as *const _ as *mut c_void,
            &mut mi as *mut _ as *mut c_void,
            &mut ki as *mut _ as *mut c_void,
            &mut bi as *mut _ as *mut c_void,
            &mut hb as *mut _ as *mut c_void,
        ];
        let grid_m = m.div_ceil(128) as u32;
        let grid_b = batch_size.div_ceil(128) as u32;
        self.launch_maybe_blob(
            "gemm_f16_x_f16_wmma_lds",
            [grid_m, grid_b, 1],
            [256, 1, 1],
            0,
            &mut params,
            || {
                let mut b = hip_bridge::KernargBlob::new();
                b.push_ptr(ap);
                b.push_ptr(xp);
                b.push_ptr(yp);
                b.push_ptr(bp);
                b.push_i32(mi);
                b.push_i32(ki);
                b.push_i32(bi);
                b.push_i32(hb);
                b
            },
        )
    }

    /// Two-level-blocked sibling of [`Gpu::gemm_f16_x_f16_wmma_lds`].
    ///
    /// Identical operand contract and identical K-accumulation order (ascending
    /// 16-element WMMA substeps), so results are bit-exact against it and
    /// against `gemm_f16_x_f16_wmma` + `bias_add_f32`. What varies is the two
    /// blocking levels, which set two independent arithmetic intensities:
    ///
    /// * block macro-tile `bm × bn` → DRAM intensity `bm·bn/(bm+bn)` FLOP/byte
    /// * wave register tile `wm × wn` → LDS intensity `wm·wn/(2·(wm+wn))`
    ///   FLOP/byte, since a wave issues `(wm/16)·(wn/16)` WMMA per k-substep
    ///   after `(wm+wn)/16` fragment loads of 1024 B each.
    ///
    /// Measurement on gfx1150 showed the shipped 128×128 / 32×64 kernel is
    /// bound by the second, not the first: widening only the block tile moved
    /// wall time by 4 % while the implied DRAM rate fell from 90 to 49 GB/s.
    /// Both levels are therefore exposed rather than fixed.
    ///
    /// `tile` must be one of [`Gpu::LDS_TILE_VARIANTS`]. Requires `K % 64 == 0`.
    ///
    /// Rows of `A` and `X` are packed at pitch `k`. Use
    /// [`Gpu::gemm_f16_x_f16_wmma_lds_tiled_ld`] to give them a wider pitch —
    /// which is worth 1.25-1.65× on the FLUX census, see the ROW PITCH note
    /// in the kernel source.
    #[allow(clippy::too_many_arguments)]
    pub fn gemm_f16_x_f16_wmma_lds_tiled(
        &mut self,
        a_f16: &GpuTensor,
        x_f16: &GpuTensor,
        y_f32: &GpuTensor,
        bias_f32: Option<&GpuTensor>,
        m: usize,
        k: usize,
        batch_size: usize,
        tile: LdsTile,
    ) -> HipResult<()> {
        self.gemm_f16_x_f16_wmma_lds_tiled_ld(
            a_f16, x_f16, y_f32, bias_f32, m, k, batch_size, tile, k, k,
        )
    }

    /// [`Gpu::gemm_f16_x_f16_wmma_lds_tiled`] with an explicit row pitch for
    /// each input operand: `A` is `[M, lda]` and `X` is `[B, ldx]`, of which
    /// only the first `k` elements of every row are read.
    ///
    /// `lda == ldx == k` is the packed contract and is bit-identical to
    /// [`Gpu::gemm_f16_x_f16_wmma_lds_tiled`]. A wider pitch changes nothing
    /// numerically — the same `k` elements are summed in the same order — it
    /// only moves where those elements sit in DRAM. That matters a great deal:
    /// a pitch that is a multiple of 1024 bytes camps the concurrent staging
    /// reads of a block's `bm + bn` rows onto a small set of channels, and
    /// every FLUX.1-dev `K` (3072, 12288, 15360) is such a pitch. See the ROW
    /// PITCH note in the kernel source for the measurement.
    ///
    /// # Panics
    ///
    /// Each pitch must be `>= k`, **a multiple of 16 elements** (the staging
    /// `half16` loads are 32-byte vector loads and only stay aligned if the
    /// pitch is), and backed by an operand long enough for it —
    /// `(rows - 1)·ld + k` elements. All three are asserted, because the kernel
    /// cannot detect any of them: it would read the wrong memory and return
    /// plausible wrong numbers.
    #[allow(clippy::too_many_arguments)]
    pub fn gemm_f16_x_f16_wmma_lds_tiled_ld(
        &mut self,
        a_f16: &GpuTensor,
        x_f16: &GpuTensor,
        y_f32: &GpuTensor,
        bias_f32: Option<&GpuTensor>,
        m: usize,
        k: usize,
        batch_size: usize,
        tile: LdsTile,
        lda: usize,
        ldx: usize,
    ) -> HipResult<()> {
        // `pipe` selects a different entry point, not a different launch
        // geometry, so it is folded into `entry()` and nothing here reads it.
        let LdsTile {
            bm,
            bn,
            wm,
            wn,
            ks,
            swap,
            pipe: _,
        } = tile;
        assert!(
            Self::LDS_TILE_VARIANTS.contains(&tile) || tile == LdsTile::HC_MIX_FILL80_GFX1100,
            "gemm_f16_x_f16_wmma_lds_tiled: no kernel for {}",
            tile.entry()
        );
        // K > 0, not just K % 64 == 0: the pipelined entries prefetch stage 0
        // before the loop is entered, so a zero-length K would read a buffer
        // that has no stage 0 to read.
        assert!(
            k > 0 && k % 64 == 0,
            "gemm_f16_x_f16_wmma_lds_tiled: K must be a positive multiple of 64 (got {k})"
        );
        if let Some(b) = bias_f32 {
            assert_eq!(
                b.dtype,
                DType::F32,
                "gemm_f16_x_f16_wmma_lds_tiled_ld: `bias_f32` must be F32"
            );
        }
        Self::check_lds_pitch(
            "gemm_f16_x_f16_wmma_lds_tiled_ld",
            a_f16,
            x_f16,
            m,
            k,
            batch_size,
            lda,
            ldx,
        );
        let _ = ks;
        let entry = tile.entry();
        // One wave per wm×wn output patch, 32 threads each.
        let threads = ((bm / wm) * (bn / wn) * 32) as u32;
        self.bind_thread()?;
        let (module, source) = self.lds256_tile_module(&entry);
        self.ensure_kernel(module, source, &entry)?;
        let ap = a_f16.buf.as_ptr();
        let xp = x_f16.buf.as_ptr();
        let yp = y_f32.buf.as_ptr();
        let bp = bias_f32.map_or(std::ptr::null_mut(), |t| t.buf.as_ptr());
        let mut mi = m as i32;
        let mut ki = k as i32;
        let mut bi = batch_size as i32;
        let mut hb = i32::from(bias_f32.is_some());
        let mut lai = lda as i32;
        let mut lxi = ldx as i32;
        let mut params: Vec<*mut c_void> = vec![
            &ap as *const _ as *mut c_void,
            &xp as *const _ as *mut c_void,
            &yp as *const _ as *mut c_void,
            &bp as *const _ as *mut c_void,
            &mut mi as *mut _ as *mut c_void,
            &mut ki as *mut _ as *mut c_void,
            &mut bi as *mut _ as *mut c_void,
            &mut hb as *mut _ as *mut c_void,
            &mut lai as *mut _ as *mut c_void,
            &mut lxi as *mut _ as *mut c_void,
        ];
        let grid_m = m.div_ceil(bm) as u32;
        let grid_b = batch_size.div_ceil(bn) as u32;
        // `swap` puts B on grid.x, which is the fastest-varying dispatch axis.
        let grid = if swap {
            [grid_b, grid_m, 1]
        } else {
            [grid_m, grid_b, 1]
        };
        self.launch_maybe_blob(&entry, grid, [threads, 1, 1], 0, &mut params, || {
            let mut b = hip_bridge::KernargBlob::new();
            b.push_ptr(ap);
            b.push_ptr(xp);
            b.push_ptr(yp);
            b.push_ptr(bp);
            b.push_i32(mi);
            b.push_i32(ki);
            b.push_i32(bi);
            b.push_i32(hb);
            b.push_i32(lai);
            b.push_i32(lxi);
            b
        })
    }

    /// Module name shared by every entry point in
    /// `GEMM_F16_X_F16_WMMA_LDS256_SRC` — the 15 `EPI = 0` tiles and the 25
    /// fused-epilogue instantiations all come out of one translation unit.
    ///
    /// `compile_and_load_kernel` caches the compiled object per MODULE name and
    /// then resolves each entry out of the loaded module, so naming the module
    /// once turns what used to be one full hipcc run per entry (~29 s each on
    /// this source, gfx1150) into a single run for all 40. It also registers
    /// each entry as an alias of that artifact for the retained-PM4 capture,
    /// exactly as the other multi-entry sources in this crate do.
    const LDS256_MODULE: &'static str = "gemm_wmma_lds256";

    /// Module and source of an `EPI = 0` LDS tile entry. #774's 64x64 k64
    /// tiles exist only in its copy of the source: module `qwen4_gemm_wmma_lds256`,
    /// except on gfx1151, where the shipped module already compiles that copy
    /// (one ~30 s JIT of this translation unit instead of two).
    fn lds256_tile_module(&self, entry: &str) -> (&'static str, &'static str) {
        lds256_tile_source_selected(self.arch_caps.is_gfx1151(), entry)
    }

    /// A/B knob for the coalesced (LDS-staged) epilogue: `HIPFIRE_LDS_EPI_DIRECT=1`
    /// compiles the same source with `WLDS_STAGE_EPILOGUE 0`, i.e. the direct
    /// store that writes along B at a stride of `4·M`. Both arms are
    /// bit-identical (the parity gate runs green either way); only the access
    /// pattern differs, so this measures the pattern and nothing else.
    ///
    /// The patched arm gets its own module name — the entry names are the same,
    /// and `functions` is keyed by entry name, so one process must load exactly
    /// one arm. That is the intended use: fresh process per arm, interleaved,
    /// with the unfused chain in `bench_gemm_epilogue` as the drift control.
    fn lds256_source(&self) -> (&'static str, std::borrow::Cow<'static, str>) {
        if hipfire_config::developer_var("HIPFIRE_LDS_EPI_DIRECT").as_deref() == Ok("1") {
            static DIRECT: OnceLock<String> = OnceLock::new();
            let src = DIRECT.get_or_init(|| {
                const FROM: &str = "#define WLDS_STAGE_EPILOGUE 1";
                // A patch that matched nothing would silently compile the
                // default arm and be written up as a null A/B result.
                let base = kernels::gemm_f16_x_f16_wmma_lds256_src(self.arch_caps.is_gfx1151());
                assert!(
                    base.contains(FROM),
                    "lds256_source: no `{FROM}` in the kernel"
                );
                base.replace(FROM, "#define WLDS_STAGE_EPILOGUE 0")
            });
            (
                "gemm_wmma_lds256_direct",
                std::borrow::Cow::Borrowed(src.as_str()),
            )
        } else {
            (
                Self::LDS256_MODULE,
                std::borrow::Cow::Borrowed(kernels::gemm_f16_x_f16_wmma_lds256_src(
                    self.arch_caps.is_gfx1151(),
                )),
            )
        }
    }

    /// The row-pitch preconditions shared by
    /// [`Gpu::gemm_f16_x_f16_wmma_lds_tiled_ld`] and
    /// [`Gpu::gemm_f16_x_f16_wmma_lds_epi_ld`]. All three are conditions the
    /// kernel cannot detect, so violating any of them reads the wrong memory
    /// and returns plausible wrong numbers rather than failing.
    ///
    /// 1. `ld >= k` — a narrower pitch would fold the next row's data into the
    ///    dot product.
    /// 2. `ld % 16 == 0` — `wlds_src` issues a `half16_t` (32-byte) vector load
    ///    at `base + row·ld + k0 + kt·16` elements. The allocation base is
    ///    256-byte aligned and every other term is a multiple of 16, so the
    ///    load is 32-byte aligned exactly when the pitch is. `k` is already a
    ///    multiple of 64, so only a pad that is not a multiple of 16 can break
    ///    it. See the PITCH PRECONDITION note in the kernel source.
    /// 3. the operands are long enough for the pitch actually being launched:
    ///    the last row read starts at `(rows - 1)·ld` and is `k` long. Without
    ///    this, adding a pad without growing the allocation reads past the end
    ///    of the buffer on every row past the first.
    #[allow(clippy::too_many_arguments)]
    fn check_lds_pitch(
        who: &str,
        a_f16: &GpuTensor,
        x_f16: &GpuTensor,
        m: usize,
        k: usize,
        batch_size: usize,
        lda: usize,
        ldx: usize,
    ) {
        assert!(
            lda >= k && ldx >= k,
            "{who}: row pitch must be >= K (got lda = {lda}, ldx = {ldx}, K = {k})"
        );
        assert!(
            lda % 16 == 0 && ldx % 16 == 0,
            "{who}: row pitch must be a multiple of 16 elements, so the staging \
             half16 loads stay 32-byte aligned (got lda = {lda}, ldx = {ldx})"
        );
        let need_a = m.saturating_sub(1) * lda + k;
        let need_x = batch_size.saturating_sub(1) * ldx + k;
        assert!(
            a_f16.numel() >= need_a,
            "{who}: A holds {} elements but M = {m} rows at lda = {lda} need {need_a}",
            a_f16.numel()
        );
        assert!(
            x_f16.numel() >= need_x,
            "{who}: X holds {} elements but B = {batch_size} rows at ldx = {ldx} need {need_x}",
            x_f16.numel()
        );
    }

    /// Every tile compiled into `GEMM_F16_X_F16_WMMA_LDS256_SRC`, in the order
    /// the bench walks them. Two wave tiles (32×64 and 64×64) across four block
    /// tiles at K stage 64, then the shallow-stage tiles that a `bn` past 256
    /// requires, then the swapped-grid controls.
    ///
    /// Rejected and not instantiated: wave tile 96×64 / 64×96 (LDS intensity
    /// 19.2) and block 256×512 at 1024 threads — all three spill. See the
    /// kernel source.
    pub const LDS_TILE_VARIANTS: &'static [LdsTile] = &[
        LdsTile::new(128, 128, 32, 64, 64, false),
        LdsTile::new(256, 128, 32, 64, 64, false),
        LdsTile::new(128, 256, 32, 64, 64, false),
        LdsTile::new(256, 256, 32, 64, 64, false),
        LdsTile::new(128, 128, 64, 64, 64, false),
        LdsTile::new(256, 128, 64, 64, 64, false),
        LdsTile::new(128, 256, 64, 64, 64, false),
        LdsTile::new(256, 256, 64, 64, 64, false),
        LdsTile::new(128, 256, 64, 64, 32, false),
        LdsTile::new(64, 512, 64, 64, 32, false),
        LdsTile::new(128, 512, 64, 64, 32, false),
        LdsTile::new(128, 512, 32, 64, 32, false),
        LdsTile::new(128, 256, 64, 64, 64, true),
        LdsTile::new(256, 128, 64, 64, 64, true),
        LdsTile::new(128, 512, 64, 64, 32, true),
        // Software-pipelined twins of the selectable tiles. 128×128 / 64×64 k64
        // is absent on purpose — it is the one tile whose pipelined form
        // spills (16 VGPRs on gfx1150). See the kernel source.
        LdsTile::new(128, 256, 32, 64, 64, false).pipelined(),
        LdsTile::new(128, 128, 32, 64, 64, false).pipelined(),
        LdsTile::new(256, 256, 64, 64, 64, false).pipelined(),
        LdsTile::new(128, 256, 64, 64, 32, false).pipelined(),
        // Short-M, long-K Qwen4 projections; see gemm_bf16_xf16_f16_wmma.
        LdsTile::new(64, 64, 32, 64, 64, false),
        LdsTile::new(64, 64, 32, 64, 64, false).pipelined(),
        // HC input_mix_down 160 x 64 (HIPFIRE_QWEN4_HC_DOWN_TILE).
        LdsTile::new(160, 64, 32, 64, 64, false),
        LdsTile::new(160, 64, 32, 64, 64, false).pipelined(),
    ];

    /// Pick a tile and dispatch it.
    ///
    /// The tile is chosen per arch from measurement, not from a model — see
    /// [`Gpu::lds_tile_for`].
    #[allow(clippy::too_many_arguments)]
    pub fn gemm_f16_x_f16_wmma_lds_auto(
        &mut self,
        a_f16: &GpuTensor,
        x_f16: &GpuTensor,
        y_f32: &GpuTensor,
        bias_f32: Option<&GpuTensor>,
        m: usize,
        k: usize,
        batch_size: usize,
    ) -> HipResult<()> {
        let cu = self.cu_count_or_default();
        let arch = self.arch.clone();
        let tile = Self::lds_pipe_gate(&arch, Self::lds_tile_for(&arch, m, batch_size, cu));
        self.gemm_f16_x_f16_wmma_lds_tiled(a_f16, x_f16, y_f32, bias_f32, m, k, batch_size, tile)
    }

    /// [`Gpu::gemm_f16_x_f16_wmma_lds_auto`] with an explicit row pitch per
    /// input operand — the pitch-aware entry a caller that stores its weights
    /// padded uses instead. `lda == ldx == k` is the packed contract and is
    /// bit-identical to [`Gpu::gemm_f16_x_f16_wmma_lds_auto`].
    ///
    /// # Panics
    ///
    /// Same pitch preconditions as
    /// [`Gpu::gemm_f16_x_f16_wmma_lds_tiled_ld`].
    #[allow(clippy::too_many_arguments)]
    pub fn gemm_f16_x_f16_wmma_lds_auto_ld(
        &mut self,
        a_f16: &GpuTensor,
        x_f16: &GpuTensor,
        y_f32: &GpuTensor,
        bias_f32: Option<&GpuTensor>,
        m: usize,
        k: usize,
        batch_size: usize,
        lda: usize,
        ldx: usize,
    ) -> HipResult<()> {
        let cu = self.cu_count_or_default();
        let arch = self.arch.clone();
        let tile = Self::lds_pipe_gate(&arch, Self::lds_tile_for(&arch, m, batch_size, cu));
        self.gemm_f16_x_f16_wmma_lds_tiled_ld(
            a_f16, x_f16, y_f32, bias_f32, m, k, batch_size, tile, lda, ldx,
        )
    }

    /// Decide the main-loop form for a selected tile: the per-arch default from
    /// [`Gpu::lds_pipe_default`], overridden by `HIPFIRE_FLUX_GEMM_PIPE` (`0`
    /// forces the plain loop, `1` forces the pipelined one). A tile with no
    /// compiled `_p` twin always gets the plain loop, so `=1` can never name an
    /// entry that was not instantiated.
    ///
    /// The knob is on the *dispatch*, not on the tile table: both arms are
    /// compiled into the same module, so an A/B is one env var against one
    /// binary with no JIT difference between the arms. The two are bit-exact,
    /// so it only ever measures the main loop — which is what makes it the
    /// right tool for the controller to settle gfx1151 and gfx1100 without a
    /// rebuild.
    pub fn lds_pipe_gate(arch: &str, tile: LdsTile) -> LdsTile {
        // One env read per process, like every other developer_var in this
        // file: the gate is on the hot dispatch path of every _auto GEMM.
        static OVERRIDE: OnceLock<Option<bool>> = OnceLock::new();
        let want = match *OVERRIDE.get_or_init(|| {
            match hipfire_config::developer_var("HIPFIRE_FLUX_GEMM_PIPE").as_deref() {
                Ok("0") => Some(false),
                Ok("1") => Some(true),
                _ => None,
            }
        }) {
            Some(forced) => forced,
            None => Self::lds_pipe_default(arch),
        };
        let piped = tile.pipelined();
        if want && Self::LDS_TILE_VARIANTS.contains(&piped) {
            piped
        } else {
            tile.unpipelined()
        }
    }

    /// Arch prefixes whose default is the software-pipelined main loop, in the
    /// same table-not-predicate shape as [`Gpu::lds_tile_preference`]: flipping
    /// an arch is a one-line edit here. Prefix matching, so `gfx1151:xnack-`
    /// and friends match.
    ///
    /// **MEASURED, one row per arch, and only measurement puts an arch here.**
    ///
    /// | arch | measurement | provenance | verdict |
    /// |---|---|---|---|
    /// | gfx1151 | **1.07×** end-to-end: 3.950 / 3.921 s/step with the pipelining on vs 4.202 s/step off (t_double 76.2 vs 78.3 ms, t_single 65.1–65.8 vs 71.4 ms) | controller, `gpu_flux_real_throughput`, real FLUX.1-dev checkpoint, f32 activation path, `HIPFIRE_FLUX_GEMM_PIPE=1` vs `=0` | **ON** |
    /// | gfx1100 | +2.6 % on its selected tile: 89.7 vs 87.4 TFLOP/s | controller, `bench_gemm_wide_lds`, 128×256 / 64×64 k32 | OFF — inside the ±3 % band |
    /// | gfx1150 | +2–3 % at the median on both its tiles (128×256 / 32×64 k64 1.03×, 128×128 / 32×64 k64 1.02×) | this box, `bench_gemm_wide_lds`, `REPS=5 WARM=1`, lock held, five runs | OFF — inside the ±3 % band |
    ///
    /// gfx1151 is the arch the prefetch was written for: it selects
    /// 256×256 / 64×64 k64, whose 64 KB of LDS pins it to a single workgroup
    /// per CU, so nothing else can cover the global-load latency. On gfx1150
    /// that same tile measures 1.15× (five runs, 1.13–1.19×) — but gfx1150 does
    /// not select it, and the tiles it does select are inside the noise band.
    /// gfx1100 already runs 2+ workgroups per CU, so the latency is covered
    /// without a prefetch, and the pipelined form of its first choice costs it
    /// real occupancy (190 VGPR / 8 waves per SIMD → 206 / 7).
    ///
    /// Unlisted archs are off; `HIPFIRE_FLUX_GEMM_PIPE=1` turns any of them on
    /// for a measurement without a rebuild.
    const LDS_PIPE_ON: &'static [&'static str] = &["gfx1151"];

    /// Whether the software-pipelined main loop is on by default for `arch`.
    /// See [`Gpu::LDS_PIPE_ON`] for the measurements behind the table.
    pub fn lds_pipe_default(arch: &str) -> bool {
        Self::LDS_PIPE_ON.iter().any(|p| arch.starts_with(p))
    }

    /// The tiles that have fused-epilogue instantiations: exactly the set
    /// [`Gpu::lds_tile_for`] can return (every per-arch preference chain plus
    /// [`Gpu::LDS_TILE_FALLBACK`]), so `gemm_f16_x_f16_wmma_lds_auto_epi` can
    /// never pick a tile without a kernel. `epi_tiles_cover_selector` asserts
    /// the two stay in sync; `WLDS_EPI_SET` in the .hip is the third copy.
    ///
    /// Widening this list is not free: five kernels per tile land in a single
    /// translation unit that the JIT compiles as a whole.
    pub const LDS_EPI_TILES: &'static [LdsTile] = &[
        LdsTile::new(128, 256, 32, 64, 64, false),
        LdsTile::new(128, 128, 32, 64, 64, false),
        LdsTile::new(256, 256, 64, 64, 64, false),
        LdsTile::new(128, 256, 64, 64, 32, false),
        LdsTile::new(128, 128, 64, 64, 64, false),
        LdsTile::new(128, 256, 32, 64, 64, false).pipelined(),
        LdsTile::new(128, 128, 32, 64, 64, false).pipelined(),
        LdsTile::new(256, 256, 64, 64, 64, false).pipelined(),
        LdsTile::new(128, 256, 64, 64, 32, false).pipelined(),
    ];

    /// [`Gpu::gemm_f16_x_f16_wmma_lds_tiled`] with a fused epilogue.
    ///
    /// Identical GEMM — same tiles, same K order, same `acc + bias` expression
    /// — with the following elementwise pass folded into the store. See
    /// [`GemmEpilogue`] for the operand contract and the evaluation order; an
    /// all-false/all-`None` `epi` is dispatched to the `EPI = 0` entry and is
    /// bit-identical to calling `gemm_f16_x_f16_wmma_lds_tiled` directly.
    ///
    /// Errors (rather than asserts) on an epilogue combination or a tile that
    /// has no compiled entry, naming the entry that would be needed. Panics if
    /// `y.dtype` disagrees with `epi.out_f16`, or if an operand is misshapen.
    #[allow(clippy::too_many_arguments)]
    pub fn gemm_f16_x_f16_wmma_lds_epi(
        &mut self,
        a_f16: &GpuTensor,
        x_f16: &GpuTensor,
        y: &GpuTensor,
        bias_f32: Option<&GpuTensor>,
        m: usize,
        k: usize,
        batch_size: usize,
        tile: LdsTile,
        epi: &GemmEpilogue<'_>,
    ) -> HipResult<()> {
        self.gemm_f16_x_f16_wmma_lds_epi_ld(
            a_f16, x_f16, y, bias_f32, m, k, batch_size, tile, epi, k, k,
        )
    }

    /// [`Gpu::gemm_f16_x_f16_wmma_lds_epi`] with an explicit row pitch for each
    /// input operand — see [`Gpu::gemm_f16_x_f16_wmma_lds_tiled_ld`] for what
    /// the pitch is for.
    #[allow(clippy::too_many_arguments)]
    pub fn gemm_f16_x_f16_wmma_lds_epi_ld(
        &mut self,
        a_f16: &GpuTensor,
        x_f16: &GpuTensor,
        y: &GpuTensor,
        bias_f32: Option<&GpuTensor>,
        m: usize,
        k: usize,
        batch_size: usize,
        tile: LdsTile,
        epi: &GemmEpilogue<'_>,
        lda: usize,
        ldx: usize,
    ) -> HipResult<()> {
        let want_dtype = if epi.out_f16 { DType::F16 } else { DType::F32 };
        assert_eq!(
            y.dtype, want_dtype,
            "gemm_f16_x_f16_wmma_lds_epi: out_f16 = {} needs a {want_dtype:?} y, got {:?}",
            epi.out_f16, y.dtype
        );
        if let Some(b) = bias_f32 {
            assert_eq!(
                b.dtype,
                DType::F32,
                "gemm_f16_x_f16_wmma_lds_epi: `bias_f32` must be F32"
            );
        }
        if epi.gate.is_some() != epi.residual.is_some() {
            return Err(hip_bridge::HipError::new(
                0,
                "gemm_f16_x_f16_wmma_lds_epi: the gated epilogue needs both `gate` ([M]) and \
                 `residual` ([B, M]); one was None",
            ));
        }
        for (name, t) in [("addin", epi.addin), ("residual", epi.residual)] {
            if let Some(t) = t {
                assert_eq!(
                    t.numel(),
                    batch_size * m,
                    "gemm_f16_x_f16_wmma_lds_epi: `{name}` must be [B, M] = [{batch_size}, {m}]"
                );
                assert_eq!(
                    t.dtype,
                    DType::F32,
                    "gemm_f16_x_f16_wmma_lds_epi: `{name}` must be F32"
                );
            }
        }
        if let Some(g) = epi.gate {
            assert_eq!(
                g.numel(),
                if epi.bf16_scaled_add { batch_size } else { m },
                "gemm_f16_x_f16_wmma_lds_epi: `gate` must be [M] = [{m}]"
            );
            assert_eq!(
                g.dtype,
                DType::F32,
                "gemm_f16_x_f16_wmma_lds_epi: `gate` must be F32"
            );
        }
        if epi.bf16_scaled_add
            && (epi.gate.is_none() || epi.out_f16 || epi.gelu || epi.addin.is_some())
        {
            return Err(hip_bridge::HipError::new(
                0,
                "BF16 scaled add requires gate and residual, with no other epilogue",
            ));
        }
        if batch_size == 0 || m == 0 {
            return Ok(());
        }

        let mask = epi.mask();
        if mask == 0 {
            // No epilogue selected: the EPI = 0 entry already is this kernel.
            return self.gemm_f16_x_f16_wmma_lds_tiled_ld(
                a_f16, x_f16, y, bias_f32, m, k, batch_size, tile, lda, ldx,
            );
        }
        let Some(suffix) = GemmEpilogue::entry_suffix(mask) else {
            return Err(hip_bridge::HipError::new(
                0,
                &format!(
                    "gemm_f16_x_f16_wmma_lds_epi: no kernel {}{} (epilogue mask {mask:#06b} is \
                     not instantiated); compiled suffixes: {}",
                    tile.entry(),
                    GemmEpilogue::describe(mask),
                    GemmEpilogue::SUPPORTED
                        .iter()
                        .map(|&(_, s)| s)
                        .collect::<Vec<_>>()
                        .join(" ")
                ),
            ));
        };
        if !Self::LDS_EPI_TILES.contains(&tile) {
            return Err(hip_bridge::HipError::new(
                0,
                &format!(
                    "gemm_f16_x_f16_wmma_lds_epi: no kernel {} (tile {} has no fused-epilogue \
                     instantiation; see Gpu::LDS_EPI_TILES)",
                    tile.entry_epi(suffix),
                    tile.label()
                ),
            ));
        }
        // K > 0 for the same reason as in `gemm_f16_x_f16_wmma_lds_tiled`.
        assert!(
            k > 0 && k % 64 == 0,
            "gemm_f16_x_f16_wmma_lds_epi: K must be a positive multiple of 64 (got {k})"
        );
        Self::check_lds_pitch(
            "gemm_f16_x_f16_wmma_lds_epi_ld",
            a_f16,
            x_f16,
            m,
            k,
            batch_size,
            lda,
            ldx,
        );

        let entry = tile.entry_epi(suffix);
        // One wave per wm×wn output patch, 32 threads each.
        let threads = ((tile.bm / tile.wm) * (tile.bn / tile.wn) * 32) as u32;
        self.bind_thread()?;
        let (module, source) = if epi.bf16_scaled_add {
            (
                "qwen4_gemm_wmma_lds256",
                std::borrow::Cow::Borrowed(kernels::QWEN4_GEMM_F16_X_F16_WMMA_LDS256_SRC),
            )
        } else {
            self.lds256_source()
        };
        self.ensure_kernel(module, &source, &entry)?;
        let ap = a_f16.buf.as_ptr();
        let xp = x_f16.buf.as_ptr();
        let yp = y.buf.as_ptr();
        let bp = bias_f32.map_or(std::ptr::null_mut(), |t| t.buf.as_ptr());
        let cp = epi.addin.map_or(std::ptr::null_mut(), |t| t.buf.as_ptr());
        let rp = epi
            .residual
            .map_or(std::ptr::null_mut(), |t| t.buf.as_ptr());
        let gp = epi.gate.map_or(std::ptr::null_mut(), |t| t.buf.as_ptr());
        let mut mi = m as i32;
        let mut ki = k as i32;
        let mut bi = batch_size as i32;
        let mut hb = i32::from(bias_f32.is_some());
        let mut lai = lda as i32;
        let mut lxi = ldx as i32;
        let mut params: Vec<*mut c_void> = vec![
            &ap as *const _ as *mut c_void,
            &xp as *const _ as *mut c_void,
            &yp as *const _ as *mut c_void,
            &bp as *const _ as *mut c_void,
            &mut mi as *mut _ as *mut c_void,
            &mut ki as *mut _ as *mut c_void,
            &mut bi as *mut _ as *mut c_void,
            &mut hb as *mut _ as *mut c_void,
            &cp as *const _ as *mut c_void,
            &rp as *const _ as *mut c_void,
            &gp as *const _ as *mut c_void,
            &mut lai as *mut _ as *mut c_void,
            &mut lxi as *mut _ as *mut c_void,
        ];
        let grid_m = m.div_ceil(tile.bm) as u32;
        let grid_b = batch_size.div_ceil(tile.bn) as u32;
        let grid = if tile.swap {
            [grid_b, grid_m, 1]
        } else {
            [grid_m, grid_b, 1]
        };
        self.launch_maybe_blob(&entry, grid, [threads, 1, 1], 0, &mut params, || {
            let mut b = hip_bridge::KernargBlob::new();
            b.push_ptr(ap);
            b.push_ptr(xp);
            b.push_ptr(yp);
            b.push_ptr(bp);
            b.push_i32(mi);
            b.push_i32(ki);
            b.push_i32(bi);
            b.push_i32(hb);
            b.push_ptr(cp);
            b.push_ptr(rp);
            b.push_ptr(gp);
            b.push_i32(lai);
            b.push_i32(lxi);
            b
        })
    }

    /// [`Gpu::gemm_f16_x_f16_wmma_lds_epi`] with the tile picked exactly as
    /// [`Gpu::gemm_f16_x_f16_wmma_lds_auto`] picks it.
    #[allow(clippy::too_many_arguments)]
    pub fn gemm_f16_x_f16_wmma_lds_auto_epi(
        &mut self,
        a_f16: &GpuTensor,
        x_f16: &GpuTensor,
        y: &GpuTensor,
        bias_f32: Option<&GpuTensor>,
        m: usize,
        k: usize,
        batch_size: usize,
        epi: &GemmEpilogue<'_>,
    ) -> HipResult<()> {
        let cu = self.cu_count_or_default();
        let arch = self.arch.clone();
        let tile = Self::lds_pipe_gate(&arch, Self::lds_tile_for(&arch, m, batch_size, cu));
        self.gemm_f16_x_f16_wmma_lds_epi(a_f16, x_f16, y, bias_f32, m, k, batch_size, tile, epi)
    }

    /// [`Gpu::gemm_f16_x_f16_wmma_lds_auto_epi`] with an explicit row pitch per
    /// input operand. `lda == ldx == k` is the packed contract and is
    /// bit-identical to [`Gpu::gemm_f16_x_f16_wmma_lds_auto_epi`].
    ///
    /// # Panics
    ///
    /// Same pitch preconditions as
    /// [`Gpu::gemm_f16_x_f16_wmma_lds_tiled_ld`].
    #[allow(clippy::too_many_arguments)]
    pub fn gemm_f16_x_f16_wmma_lds_auto_epi_ld(
        &mut self,
        a_f16: &GpuTensor,
        x_f16: &GpuTensor,
        y: &GpuTensor,
        bias_f32: Option<&GpuTensor>,
        m: usize,
        k: usize,
        batch_size: usize,
        epi: &GemmEpilogue<'_>,
        lda: usize,
        ldx: usize,
    ) -> HipResult<()> {
        let cu = self.cu_count_or_default();
        let arch = self.arch.clone();
        let tile = Self::lds_pipe_gate(&arch, Self::lds_tile_for(&arch, m, batch_size, cu));
        self.gemm_f16_x_f16_wmma_lds_epi_ld(
            a_f16, x_f16, y, bias_f32, m, k, batch_size, tile, epi, lda, ldx,
        )
    }

    /// Tile choice for [`Gpu::gemm_f16_x_f16_wmma_lds_auto`], factored out so it
    /// is unit-testable without a GPU.
    ///
    /// The preference order is **measured per arch**, because the winner is not
    /// the same on all three (`bench_gemm_wide_lds`, median of 5, fresh
    /// process, lock held, summed over the four FLUX.1-dev census shapes at
    /// their real per-step call counts, against the shipped 128×128 / 32×64
    /// tiling):
    ///
    /// | tile                | gfx1150 | gfx1151 | gfx1100 |
    /// |---------------------|---------|---------|---------|
    /// | 128×256 / 32×64 k64 | **1.19**|  1.23   |  1.11   |
    /// | 256×256 / 64×64 k64 |  1.06   | **1.29**|  1.59   |
    /// | 128×256 / 64×64 k32 |  0.86   |  0.66   | **1.75**|
    ///
    /// gfx1100's winner is a 43 % loss on gfx1151, so a single portable choice
    /// would give up most of the win — this is the same "winner on one arch is
    /// the loser on another" pattern the attention work already recorded. Every
    /// listed tile is a win on the arch it is listed for; unknown archs get the
    /// one that is positive on all three.
    ///
    /// This picks the *tile*. Whether that tile's main loop is
    /// software-pipelined is a separate, orthogonal decision made afterwards by
    /// [`Gpu::lds_pipe_gate`] — the chains here name plain tiles only.
    ///
    /// A tile is skipped when it is wider than the operand it tiles, or when
    /// its grid would not produce at least `cu_count / 2` workgroups — past
    /// that point the launch tail costs more than the tile wins.
    pub fn lds_tile_for(arch: &str, m: usize, batch_size: usize, cu_count: usize) -> LdsTile {
        let min_blocks = (cu_count / 2).max(1);
        for &t in Self::lds_tile_preference(arch) {
            let fits = m >= t.bm && batch_size >= t.bn;
            let blocks = m.div_ceil(t.bm) * batch_size.div_ceil(t.bn);
            if fits && blocks >= min_blocks {
                return t;
            }
        }
        Self::LDS_TILE_FALLBACK
    }

    /// Measured descending preference per arch. See [`Gpu::lds_tile_for`].
    fn lds_tile_preference(arch: &str) -> &'static [LdsTile] {
        // Plain tiles only: the main-loop form is orthogonal to the tile and is
        // decided afterwards by `lds_pipe_gate`, so it stays one env var away
        // from an A/B on any arch.
        const GFX1150: &[LdsTile] = &[
            LdsTile::new(128, 256, 32, 64, 64, false),
            LdsTile::new(128, 128, 32, 64, 64, false),
        ];
        const GFX1151: &[LdsTile] = &[
            LdsTile::new(256, 256, 64, 64, 64, false),
            LdsTile::new(128, 256, 32, 64, 64, false),
            LdsTile::new(128, 128, 32, 64, 64, false),
        ];
        const GFX1100: &[LdsTile] = &[
            LdsTile::new(128, 256, 64, 64, 32, false),
            // The only selectable tile with no pipelined twin at all: its
            // pipelined form spills. See the kernel source.
            LdsTile::new(128, 128, 64, 64, 64, false),
        ];
        // Unmeasured archs (gfx1101/1102/1103, gfx12xx): the tile that is a win
        // on all three measured parts, at 48 KB of LDS rather than 64.
        const PORTABLE: &[LdsTile] = &[
            LdsTile::new(128, 256, 32, 64, 64, false),
            LdsTile::new(128, 128, 32, 64, 64, false),
        ];
        match arch {
            a if a.starts_with("gfx1150") => GFX1150,
            a if a.starts_with("gfx1151") => GFX1151,
            a if a.starts_with("gfx1100") => GFX1100,
            _ => PORTABLE,
        }
    }

    /// Used when no preferred tile fits the shape. Reproduces the shipped
    /// `gemm_f16_x_f16_wmma_lds` tiling exactly.
    const LDS_TILE_FALLBACK: LdsTile = LdsTile::new(128, 128, 32, 64, 64, false);

    /// CU count for tile selection. Falls back to 16 (the smallest RDNA3 iGPU
    /// config) when the device property is unavailable, which biases the
    /// selector toward the wide tile rather than toward the narrow one.
    pub(crate) fn cu_count_or_default(&self) -> usize {
        self.hip
            .get_device_attribute(
                crate::profiler::HIP_DEVICE_ATTRIBUTE_MULTIPROCESSOR_COUNT,
                self.device_id,
            )
            .ok()
            .filter(|&v| v > 0)
            .map(|v| crate::profiler::hip_mp_count_to_cu_count(&self.arch, v as u32) as usize)
            .filter(|&v| (4..=256).contains(&v))
            .unwrap_or(16)
    }

    pub fn gemm_f32_register_tiled(
        &mut self,
        a: &GpuTensor,
        x: &GpuTensor,
        y: &GpuTensor,
        m: usize,
        k: usize,
        batch_size: usize,
    ) -> HipResult<()> {
        self.bind_thread()?;
        let (kname, src, batch_tile, block_x) = (
            "gemm_f32_register_tiled",
            kernels::GEMM_F32_REGISTER_TILED_SRC,
            8u32,
            32u32,
        );
        self.ensure_kernel(kname, src, kname)?;
        let mut ap = a.buf.as_ptr();
        let mut xp = x.buf.as_ptr();
        let mut yp = y.buf.as_ptr();
        let mut mi = m as i32;
        let mut ki = k as i32;
        let mut bs = batch_size as i32;
        let mut params: Vec<*mut c_void> = vec![
            &mut ap as *mut _ as *mut c_void,
            &mut xp as *mut _ as *mut c_void,
            &mut yp as *mut _ as *mut c_void,
            &mut mi as *mut _ as *mut c_void,
            &mut ki as *mut _ as *mut c_void,
            &mut bs as *mut _ as *mut c_void,
        ];
        let grid_y = (batch_size as u32 + batch_tile - 1) / batch_tile;
        launch_params_blob!(
            self,
            kname,
            [m as u32, grid_y, 1],
            [block_x, 1, 1],
            0,
            params; ap, xp, yp, mi, ki, bs
        )
    }
    /// Waves per block in the low-bit WMMA prefill GEMMs. Each wave owns a
    /// 16-row tile and they share one LDS-staged activation tile, so x is read
    /// from global once per (16 * this) rows. Must match
    /// HIPFIRE_LOWBIT_WMMA_WAVES in the kernel sources.
    pub const LOWBIT_WMMA_WAVES: usize = 16;

    /// WMMA prefill GEMM for TQ2-G128 packed weights + F32 activations.
    /// `x_f32` is [batch x k] F32 (converted to F16 fragments in-register,
    /// so this drops into the existing F32 prefill pipeline unchanged);
    /// `y_f32` is [batch x m] F32.
    pub fn gemm_tq2g128_wmma(
        &mut self,
        a_raw: &GpuTensor,
        x_f32: &GpuTensor,
        y_f32: &GpuTensor,
        m: usize,
        k: usize,
        batch_size: usize,
    ) -> HipResult<()> {
        self.gemm_lowbit_wmma(
            "gemm_tq2g128_wmma",
            kernels::GEMM_TQ2G128_WMMA_SRC,
            a_raw,
            x_f32,
            y_f32,
            m,
            k,
            batch_size,
        )
    }

    /// Binary sibling of [`Self::gemm_tq2g128_wmma`].
    pub fn gemm_bq1g128_wmma(
        &mut self,
        a_raw: &GpuTensor,
        x_f32: &GpuTensor,
        y_f32: &GpuTensor,
        m: usize,
        k: usize,
        batch_size: usize,
    ) -> HipResult<()> {
        self.gemm_lowbit_wmma(
            "gemm_bq1g128_wmma",
            kernels::GEMM_BQ1G128_WMMA_SRC,
            a_raw,
            x_f32,
            y_f32,
            m,
            k,
            batch_size,
        )
    }

    /// Shared body for the two low-bit WMMA GEMMs: same kernargs and the same
    /// [ceil(M/16), ceil(B/16)] x [32] geometry, differing only in source.
    #[allow(clippy::too_many_arguments)]
    fn gemm_lowbit_wmma(
        &mut self,
        name: &'static str,
        src: &'static str,
        a_raw: &GpuTensor,
        x_f32: &GpuTensor,
        y_f32: &GpuTensor,
        m: usize,
        k: usize,
        batch_size: usize,
    ) -> HipResult<()> {
        assert_eq!(k % 128, 0, "{name}: k must be a multiple of 128, got {k}");
        self.bind_thread()?;
        self.ensure_kernel(name, src, name)?;
        let ap = a_raw.buf.as_ptr();
        let xp = x_f32.buf.as_ptr();
        let yp = y_f32.buf.as_ptr();
        let mut mi = m as i32;
        let mut ki = k as i32;
        let mut bi = batch_size as i32;
        let mut params: Vec<*mut c_void> = vec![
            &ap as *const _ as *mut c_void,
            &xp as *const _ as *mut c_void,
            &yp as *const _ as *mut c_void,
            &mut mi as *mut _ as *mut c_void,
            &mut ki as *mut _ as *mut c_void,
            &mut bi as *mut _ as *mut c_void,
        ];
        launch_params_blob!(
            self,
            name,
            // 16 rows per wave x LOWBIT_WMMA_WAVES waves per block; the
            // block shares one LDS-staged x tile.
            [
                m.div_ceil(16 * Self::LOWBIT_WMMA_WAVES) as u32,
                batch_size.div_ceil(64) as u32,
                1,
            ],
            [32 * Self::LOWBIT_WMMA_WAVES as u32, 1, 1],
            0,
            params; ap, xp, yp, mi, ki, bi
        )
    }

    pub fn gemm_hfq4g256_wmma(
        &mut self,
        a_raw: &GpuTensor,
        x_f16: &GpuTensor,
        y_f32: &GpuTensor,
        m: usize,
        k: usize,
        batch_size: usize,
    ) -> HipResult<()> {
        self.bind_thread()?;
        self.ensure_kernel(
            "gemm_hfq4g256_wmma",
            kernels::GEMM_HFQ4G256_WMMA_SRC,
            "gemm_hfq4g256_wmma",
        )?;
        let ap = a_raw.buf.as_ptr();
        let xp = x_f16.buf.as_ptr();
        let yp = y_f32.buf.as_ptr();
        let mut mi = m as i32;
        let mut ki = k as i32;
        let mut bi = batch_size as i32;
        let mut params: Vec<*mut c_void> = vec![
            &ap as *const _ as *mut c_void,
            &xp as *const _ as *mut c_void,
            &yp as *const _ as *mut c_void,
            &mut mi as *mut _ as *mut c_void,
            &mut ki as *mut _ as *mut c_void,
            &mut bi as *mut _ as *mut c_void,
        ];
        let grid_m = ((m + 15) / 16) as u32;
        let grid_b = ((batch_size + 15) / 16) as u32;
        launch_params_blob!(
            self,
            "gemm_hfq4g256_wmma",
            [grid_m, grid_b, 1],
            [32, 1, 1],
            0,
            params; ap, xp, yp, mi, ki, bi
        )
    }
    pub fn gemm_mq2g256_lloyd_moe_grouped_wmma_k2(
        &mut self,
        expert_weight_ptrs: &GpuTensor,
        expert_tile_ids: &GpuTensor,
        sorted_slot_index: &GpuTensor,
        x_src: &GpuTensor,
        y_grouped: &GpuTensor,
        m: usize,
        k: usize,
        x_row_div: usize,
        m_total: usize,
        x_src_rows: usize,
    ) -> HipResult<()> {
        self.bind_thread()?;
        let n_experts_val = moe_expert_table_len(expert_weight_ptrs);
        let kernel_name = "gemm_mq2g256_lloyd_moe_grouped_wmma_k2";
        let kernel_src = kernels::GEMM_MQ2G256_LLOYD_MOE_GROUPED_WMMA_K2_SRC;
        self.ensure_kernel(kernel_name, kernel_src, kernel_name)?;
        let x_f16_ptr = self.ensure_fp16_x(x_src, x_src_rows * k)?;

        let ep = expert_weight_ptrs.buf.as_ptr();
        let tp = expert_tile_ids.buf.as_ptr();
        let sp = sorted_slot_index.buf.as_ptr();
        let xp = x_f16_ptr;
        let yp = y_grouped.buf.as_ptr();
        let m_val = m as i32;
        let k_val = k as i32;
        let xrd_val = x_row_div as i32;
        let mt_val = m_total as i32;

        let mut params: Vec<*mut c_void> = vec![
            &ep as *const _ as *mut c_void,
            &tp as *const _ as *mut c_void,
            &sp as *const _ as *mut c_void,
            &xp as *const _ as *mut c_void,
            &yp as *const _ as *mut c_void,
            &m_val as *const _ as *mut c_void,
            &k_val as *const _ as *mut c_void,
            &xrd_val as *const _ as *mut c_void,
            &mt_val as *const _ as *mut c_void,
            &n_experts_val as *const _ as *mut c_void,
        ];

        let row_tiles = ((m + 15) / 16) as u32;
        let slot_tiles = ((m_total + 15) / 16) as u32;
        // BW: MQ2-Lloyd weight is 72 B/group, half of HFQ4's 136 B/group.
        let mq2_weight_bytes = m * (k / 256) * 72;
        let bytes = m_total * k * 2 + (m_total * m) * 4 + mq2_weight_bytes;
        let timer = crate::profile::begin_timer(&self.hip, "gemm", kernel_name, bytes);
        let result = self.launch_maybe_blob(
            kernel_name,
            [row_tiles, slot_tiles, 1],
            [32, 1, 1],
            0,
            &mut params,
            || {
                let mut b = hip_bridge::KernargBlob::new();
                b.push_ptr(ep);
                b.push_ptr(tp);
                b.push_ptr(sp);
                b.push_ptr(xp);
                b.push_ptr(yp);
                b.push_i32(m_val);
                b.push_i32(k_val);
                b.push_i32(xrd_val);
                b.push_i32(mt_val);
                b.push_i32(n_experts_val);
                b
            },
        );
        if let Some(t) = timer {
            t.finish(&self.hip);
        }
        result
    }
    pub fn gemm_mq2g256_lloyd_moe_grouped_wmma_4w_k2(
        &mut self,
        expert_weight_ptrs: &GpuTensor,
        expert_tile_ids: &GpuTensor,
        sorted_slot_index: &GpuTensor,
        x_src: &GpuTensor,
        y_grouped: &GpuTensor,
        m: usize,
        k: usize,
        x_row_div: usize,
        m_total: usize,
        x_src_rows: usize,
    ) -> HipResult<()> {
        self.bind_thread()?;
        let n_experts_val = moe_expert_table_len(expert_weight_ptrs);
        debug_assert_eq!(
            m % 64,
            0,
            "gemm_mq2g256_lloyd_moe_grouped_wmma_4w_k2: M must be a multiple of 64 (got {m})"
        );
        debug_assert_eq!(
            k % 256,
            0,
            "gemm_mq2g256_lloyd_moe_grouped_wmma_4w_k2: K must be a multiple of 256 (got {k})"
        );
        let (kernel_name, kernel_src) = if self.arch_caps.has_wmma_w32_gfx12() {
            (
                "gemm_mq2g256_lloyd_moe_grouped_wmma_4w_k2_gfx12",
                kernels::GEMM_MQ2G256_LLOYD_MOE_GROUPED_WMMA_4W_K2_GFX12_SRC,
            )
        } else {
            (
                "gemm_mq2g256_lloyd_moe_grouped_wmma_4w_k2",
                kernels::GEMM_MQ2G256_LLOYD_MOE_GROUPED_WMMA_4W_K2_SRC,
            )
        };
        self.ensure_kernel(kernel_name, kernel_src, kernel_name)?;
        let x_f16_ptr = self.ensure_fp16_x(x_src, x_src_rows * k)?;

        let ep = expert_weight_ptrs.buf.as_ptr();
        let tp = expert_tile_ids.buf.as_ptr();
        let sp = sorted_slot_index.buf.as_ptr();
        let xp = x_f16_ptr;
        let yp = y_grouped.buf.as_ptr();
        let m_val = m as i32;
        let k_val = k as i32;
        let xrd_val = x_row_div as i32;
        let mt_val = m_total as i32;

        let mut params: Vec<*mut c_void> = vec![
            &ep as *const _ as *mut c_void,
            &tp as *const _ as *mut c_void,
            &sp as *const _ as *mut c_void,
            &xp as *const _ as *mut c_void,
            &yp as *const _ as *mut c_void,
            &m_val as *const _ as *mut c_void,
            &k_val as *const _ as *mut c_void,
            &xrd_val as *const _ as *mut c_void,
            &mt_val as *const _ as *mut c_void,
            &n_experts_val as *const _ as *mut c_void,
        ];

        // Row tiles widen 16 → 64; slot tiles unchanged at 16.
        let row_tiles = ((m + 63) / 64) as u32;
        let slot_tiles = ((m_total + 15) / 16) as u32;
        // BW unchanged from baseline: same total data movement, the
        // win is in B-fragment cache reuse across warps.
        let mq2_weight_bytes = m * (k / 256) * 72;
        let bytes = m_total * k * 2 + (m_total * m) * 4 + mq2_weight_bytes;
        let timer = crate::profile::begin_timer(&self.hip, "gemm", kernel_name, bytes);
        let result = self.launch_maybe_blob(
            kernel_name,
            [row_tiles, slot_tiles, 1],
            [128, 1, 1],
            0,
            &mut params,
            || {
                let mut b = hip_bridge::KernargBlob::new();
                b.push_ptr(ep);
                b.push_ptr(tp);
                b.push_ptr(sp);
                b.push_ptr(xp);
                b.push_ptr(yp);
                b.push_i32(m_val);
                b.push_i32(k_val);
                b.push_i32(xrd_val);
                b.push_i32(mt_val);
                b.push_i32(n_experts_val);
                b
            },
        );
        if let Some(t) = timer {
            t.finish(&self.hip);
        }
        result
    }
